from (values
(347268,38586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, er hat mir gesagt, bis zehn wird sie eine ganze Stunde lang Geräte ...'::text,'ausgesteckt haben'::text,'ausstecken'::text,'ausstecken'::text,'Warte, er hat mir gesagt, bis zehn wird sie eine ganze Stunde lang Geräte ausgesteckt haben.'::text),
(347272,38586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зачекай, він сказав мені, що до десятої вона ... пристрої з розеток цілу годину.'::text,'вимикатиме'::text,'вимикатиме'::text,'вимкне'::text,'Зачекай, він сказав мені, що до десятої вона вимикатиме пристрої з розеток цілу годину.'::text),
(347271,38586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, me dijo que para las diez ella ... aparatos durante una hora entera.'::text,'habrá estado desenchufando'::text,'estará desenchufando'::text,'desenchufará'::text,'Espera, me dijo que para las diez ella habrá estado desenchufando aparatos durante una hora entera.'::text),
(347270,38586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, il m''a dit qu''à dix heures, elle ... des appareils pendant une heure entière.'::text,'aura débranché'::text,'sera en train de débrancher'::text,'débranchera'::text,'Attends, il m''a dit qu''à dix heures, elle aura débranché des appareils pendant une heure entière.'::text),
(347273,38586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur bir dakika, bana dedi ki saat ona kadar tam bir saat boyunca cihazların fişini ...'::text,'çekmiş olacak'::text,'çekiyor olacak'::text,'çekecek'::text,'Dur bir dakika, bana dedi ki saat ona kadar tam bir saat boyunca cihazların fişini çekmiş olacak.'::text),
(347274,38586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt mondta, tízkor már egy teljes órája ... a készülékeket a konnektorból.'::text,'húzza ki'::text,'ki fogja húzni'::text,'kihúzza'::text,'Várj, azt mondta, tízkor már egy teljes órája húzza ki a készülékeket a konnektorból.'::text),
(347277,38587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Fernseher eingesteckt gelassen hätte, ... das Gerät die ganze Nacht Strom verbraucht.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie den Fernseher eingesteckt gelassen hätte, hätte das Gerät die ganze Nacht Strom verbraucht.'::text),
(347281,38587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона залишила телевізор увімкненим у розетку, пристрій ... електроенергію всю ніч.'::text,'споживав би'::text,'споживатиме'::text,'споживав'::text,'Якби вона залишила телевізор увімкненим у розетку, пристрій споживав би електроенергію всю ніч.'::text),
(347280,38587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera dejado la tele enchufada, el aparato ... electricidad toda la noche.'::text,'habría consumido'::text,'consumirá'::text,'consumió'::text,'Si hubiera dejado la tele enchufada, el aparato habría consumido electricidad toda la noche.'::text),
(347279,38587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait laissé la télé branchée, l''appareil ... de l''électricité toute la nuit.'::text,'aurait consommé'::text,'consommera'::text,'a consommé'::text,'Si elle avait laissé la télé branchée, l''appareil aurait consommé de l''électricité toute la nuit.'::text),
(347282,38587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Televizyonu fişte bıraksaydı, cihaz bütün gece elektrik ...'::text,'harcamış olurdu'::text,'harcayacak'::text,'harcadı'::text,'Televizyonu fişte bıraksaydı, cihaz bütün gece elektrik harcamış olurdu.'::text),
(347283,38587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha bedugva hagyta volna a tévét, a készülék egész éjjel ... az áramot.'::text,'fogyasztotta volna'::text,'fogyasztani fogja'::text,'fogyasztotta'::text,'Ha bedugva hagyta volna a tévét, a készülék egész éjjel fogyasztotta volna az áramot.'::text),
(347286,38588,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn sie nicht jedes Gerät ausgesteckt hätte, ... die Wohnung jetzt ziemlich hell.'::text,'wäre'::text,'wäre'::text,'wird'::text,'Digga, wenn sie nicht jedes Gerät ausgesteckt hätte, wäre die Wohnung jetzt ziemlich hell.'::text),
(347290,38588,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби вона не вимкнула кожен пристрій, у квартирі ... зараз доволі світло.'::text,'було б'::text,'було б'::text,'буде'::text,'Бро, якби вона не вимкнула кожен пристрій, у квартирі було б зараз доволі світло.'::text),
(347289,38588,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si no hubiera desenchufado todos los aparatos, el piso ... bastante iluminado ahora mismo.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Bro, si no hubiera desenchufado todos los aparatos, el piso estaría bastante iluminado ahora mismo.'::text),
(347288,38588,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si elle n''avait pas débranché chaque appareil, l''appart ... plutôt lumineux en ce moment.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Frérot, si elle n''avait pas débranché chaque appareil, l''appart serait plutôt lumineux en ce moment.'::text),
(347291,38588,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her cihazın fişini çekmeseydi, daire şu an epey aydınlık ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Kanka, her cihazın fişini çekmeseydi, daire şu an epey aydınlık olurdu.'::text),
(347292,38588,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem húzott volna ki minden készüléket, a lakás most elég világos ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Tesó, ha nem húzott volna ki minden készüléket, a lakás most elég világos lenne.'::text),
(347295,38589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man sagt, der Standventilator ... tagelang an, bevor sie das Gerät aussteckte.'::text,'war'::text,'ist'::text,'ist'::text,'Man sagt, der Standventilator war tagelang an, bevor sie das Gerät aussteckte.'::text),
(347299,38589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що підлоговий вентилятор ... увімкнений кілька днів, перш ніж вона вимкнула пристрій.'::text,'був'::text,'є'::text,'є'::text,'Кажуть, що підлоговий вентилятор був увімкнений кілька днів, перш ніж вона вимкнула пристрій.'::text),
(347298,38589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el ventilador de pie ... encendido durante días antes de que ella desenchufara el aparato.'::text,'había estado'::text,'está'::text,'está'::text,'Se dice que el ventilador de pie había estado encendido durante días antes de que ella desenchufara el aparato.'::text),
(347297,38589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le ventilateur sur pied ... allumé pendant des jours avant qu''elle ne débranche l''appareil.'::text,'était resté'::text,'est'::text,'est'::text,'On dit que le ventilateur sur pied était resté allumé pendant des jours avant qu''elle ne débranche l''appareil.'::text),
(347300,38589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayaklı vantilatörün, o cihazın fişini çekmeden önce günlerce açık ... söyleniyor.'::text,'kaldığı'::text,'olduğu'::text,'olduğu'::text,'Ayaklı vantilatörün, o cihazın fişini çekmeden önce günlerce açık kaldığı söyleniyor.'::text),
(347301,38589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, az állóventilátor napokig ... bekapcsolva, mielőtt kihúzta a készüléket.'::text,'volt'::text,'van'::text,'van'::text,'Azt mondják, az állóventilátor napokig volt bekapcsolva, mielőtt kihúzta a készüléket.'::text),
(347304,38590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schlug vor, jedes Gerät um 22 Uhr ..., um das Energiebudget zu senken.'::text,'auszustecken'::text,'auszustecken'::text,'ausgesteckt'::text,'Sie schlug vor, jedes Gerät um 22 Uhr auszustecken, um das Energiebudget zu senken.'::text),
(347308,38590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона запропонувала ... кожен пристрій о 22:00, щоб скоротити енергетичний бюджет.'::text,'вимикати'::text,'вимкнути'::text,'вимкнула'::text,'Вона запропонувала вимикати кожен пристрій о 22:00, щоб скоротити енергетичний бюджет.'::text),
