(347306,38590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a proposé de ... chaque appareil à 22 h pour réduire le budget énergétique.'::text,'débrancher'::text,'débrancher'::text,'débranché'::text,'Elle a proposé de débrancher chaque appareil à 22 h pour réduire le budget énergétique.'::text),
(347309,38590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enerji bütçesini azaltmak için saat 22.00''de her cihazın fişini ... önerdi.'::text,'çekmeyi'::text,'çekmeyi'::text,'çekti'::text,'Enerji bütçesini azaltmak için saat 22.00''de her cihazın fişini çekmeyi önerdi.'::text),
(347310,38590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt javasolta, hogy este 10-kor ... minden készüléket, hogy csökkentsék az energiaköltségvetést.'::text,'húzzák ki'::text,'húzzák ki'::text,'kihúzta'::text,'Azt javasolta, hogy este 10-kor húzzák ki minden készüléket, hogy csökkentsék az energiaköltségvetést.'::text),
(347313,38591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hätte die Geräte früher ..., weil die Lichter den ganzen Tag an waren.'::text,'ausstecken sollen'::text,'ausstecken müssen'::text,'nicht ausstecken können'::text,'Sie hätte die Geräte früher ausstecken sollen, weil die Lichter den ganzen Tag an waren.'::text),
(347317,38591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... пристрої раніше, бо світло горіло весь день.'::text,'мала вимкнути'::text,'напевно вимкнула'::text,'не може вимкнути'::text,'Вона мала вимкнути пристрої раніше, бо світло горіло весь день.'::text),
(347316,38591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los aparatos antes, porque las luces estuvieron encendidas todo el día.'::text,'Debería haber desenchufado'::text,'Debe de haber desenchufado'::text,'No puede desenchufar'::text,'Debería haber desenchufado los aparatos antes, porque las luces estuvieron encendidas todo el día.'::text),
(347315,38591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les appareils plus tôt, parce que les lumières étaient allumées toute la journée.'::text,'aurait dû débrancher'::text,'a dû débrancher'::text,'ne peut pas débrancher'::text,'Elle aurait dû débrancher les appareils plus tôt, parce que les lumières étaient allumées toute la journée.'::text),
(347318,38591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işıklar bütün gün açık kaldığı için cihazların fişini daha erken ...'::text,'çekmeliydi'::text,'çekmiş olmalı'::text,'çekemez'::text,'Işıklar bütün gün açık kaldığı için cihazların fişini daha erken çekmeliydi.'::text),
(347319,38591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korábban ... a készülékeket, mert egész nap égtek a lámpák.'::text,'ki kellett volna húznia'::text,'biztosan kihúzta'::text,'nem húzhatja ki'::text,'Korábban ki kellett volna húznia a készülékeket, mert egész nap égtek a lámpák.'::text),
(347322,38592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst nachdem sie das letzte Gerät ausgesteckt hatte, ... wurde die Wohnung dunkel.'::text,''::text,'sie'::text,'war'::text,'Erst nachdem sie das letzte Gerät ausgesteckt hatte, wurde die Wohnung dunkel.'::text),
(347326,38592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише після того, як вона вимкнула останній пристрій, ... квартира потемніла.'::text,''::text,'вона'::text,'була'::text,'Лише після того, як вона вимкнула останній пристрій, квартира потемніла.'::text),
(347325,38592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo después de desenchufar el último aparato ... el piso se quedó a oscuras.'::text,''::text,'ella'::text,'estaba'::text,'Solo después de desenchufar el último aparato el piso se quedó a oscuras.'::text),
(347324,38592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est qu''après avoir débranché le dernier appareil que ... l''appart est devenu sombre.'::text,''::text,'elle'::text,'était'::text,'Ce n''est qu''après avoir débranché le dernier appareil que l''appart est devenu sombre.'::text),
(347327,38592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak son cihazın fişini çektikten sonra ... daire karardı.'::text,''::text,'o'::text,NULL::text,'Ancak son cihazın fişini çektikten sonra daire karardı.'::text),
(347328,38592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak miután kihúzta az utolsó készüléket, ... sötétült el a lakás.'::text,''::text,'ő'::text,'volt'::text,'Csak miután kihúzta az utolsó készüléket, sötétült el a lakás.'::text),
(347331,38593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie könnte ihre Mitbewohnerin die Geräte ... lassen, aber sie macht es selbst.'::text,'ausstecken'::text,'ausstecken'::text,'ausgesteckt'::text,'Sie könnte ihre Mitbewohnerin die Geräte ausstecken lassen, aber sie macht es selbst.'::text),
(347335,38593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона могла б попросити сусідку по квартирі ... пристрої, але робить це сама.'::text,'вимкнути'::text,'вимкнути'::text,'вимкнула'::text,'Вона могла б попросити сусідку по квартирі вимкнути пристрої, але робить це сама.'::text),
(347334,38593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Podría pedirle a su compañera de piso que ... los aparatos, pero lo hace ella misma.'::text,'desenchufe'::text,'desenchufe'::text,'desenchufó'::text,'Podría pedirle a su compañera de piso que desenchufe los aparatos, pero lo hace ella misma.'::text),
(347333,38593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pourrait faire ... les appareils à sa coloc, mais elle le fait elle-même.'::text,'débrancher'::text,'débrancher'::text,'débranché'::text,'Elle pourrait faire débrancher les appareils à sa coloc, mais elle le fait elle-même.'::text),
(347336,38593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev arkadaşına cihazların fişini ... ama kendisi yapıyor.'::text,'çektirebilirdi'::text,'çektirebilirdi'::text,'çekti'::text,'Ev arkadaşına cihazların fişini çektirebilirdi ama kendisi yapıyor.'::text),
(347337,38593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkérhetné a lakótársát, hogy ... a készülékeket, de ő maga csinálja.'::text,'húzza ki'::text,'húzza ki'::text,'kihúzta'::text,'Megkérhetné a lakótársát, hogy húzza ki a készülékeket, de ő maga csinálja.'::text),
(347340,38594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, jedes Gerät ... sich von selbst ab. Ein entspannter Abend, ganz klar.'::text,'schaltete'::text,'schaltet'::text,'schaltet'::text,'Sie wünscht sich, jedes Gerät schaltete sich von selbst ab. Ein entspannter Abend, ganz klar.'::text),
(347344,38594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хоче, щоб кожен пристрій ... сам. Розслаблений вечір, звісно.'::text,'вимикався'::text,'вимкнеться'::text,'вимикається'::text,'Вона хоче, щоб кожен пристрій вимикався сам. Розслаблений вечір, звісно.'::text),
(347343,38594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gustaría que cada aparato ... solo. Una noche relajada, clarísimo.'::text,'se apagara'::text,'se apagará'::text,'se apaga'::text,'Le gustaría que cada aparato se apagara solo. Una noche relajada, clarísimo.'::text),
(347342,38594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait que chaque appareil ... tout seul. Une soirée relaxante, clairement.'::text,'s''éteigne'::text,'s''éteindra'::text,'s''éteint'::text,'Elle aimerait que chaque appareil s''éteigne tout seul. Une soirée relaxante, clairement.'::text),
(347345,38594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her cihazın kendi kendine ... istiyor. Ne rahatlatıcı bir akşam, belli.'::text,'kapanmasını'::text,'kapanacağını'::text,'kapandığını'::text,'Her cihazın kendi kendine kapanmasını istiyor. Ne rahatlatıcı bir akşam, belli.'::text),
(347346,38594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha minden készülék ... magától. Pihentető este, nyilván.'::text,'kikapcsolna'::text,'ki fog kapcsolni'::text,'kikapcsol'::text,'Azt szeretné, ha minden készülék kikapcsolna magától. Pihentető este, nyilván.'::text),
(347349,38595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fernseher, ... LED-Lichter in einer Sekunde ausgingen, war das letzte Gerät, das zusammenbrach!'::text,'dessen'::text,'der'::text,'der'::text,'Der Fernseher, dessen LED-Lichter in einer Sekunde ausgingen, war das letzte Gerät, das zusammenbrach!'::text),
(347353,38595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Телевізор, ... світлодіоди згасли за секунду, був останнім пристроєм, що впав!'::text,'чиї'::text,'який'::text,'що'::text,'Телевізор, чиї світлодіоди згасли за секунду, був останнім пристроєм, що впав!'::text),
