(362019,40225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, mein Kumpel ... sich die ganze Woche wegen dieser Spritze gestresst, bevor es zwei Sekunden dauerte, kein Witz.'::text,'hatte'::text,'hat'::text,'hat'::text,'Ehrlich, mein Kumpel hatte sich die ganze Woche wegen dieser Spritze gestresst, bevor es zwei Sekunden dauerte, kein Witz.'::text),
(362023,40225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно кажучи, мій бро ... через той укол цілий тиждень, а потім усе зайняло дві секунди, реально.'::text,'переживав'::text,'переживає'::text,'переживав'::text,'Чесно кажучи, мій бро переживав через той укол цілий тиждень, а потім усе зайняло дві секунди, реально.'::text),
(362022,40225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sin mentir, mi colega ... por esa inyección toda la semana y luego tardó dos segundos, en serio.'::text,'había estado agobiado'::text,'ha estado agobiado'::text,'estaba agobiado'::text,'Sin mentir, mi colega había estado agobiado por esa inyección toda la semana y luego tardó dos segundos, en serio.'::text),
(362021,40225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, mon pote ... pour cette piqûre toute la semaine avant que ça dure deux secondes, sans mentir.'::text,'avait stressé'::text,'a stressé'::text,'stressait'::text,'Franchement, mon pote avait stressé pour cette piqûre toute la semaine avant que ça dure deux secondes, sans mentir.'::text),
(362024,40225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, kanka bütün hafta o iğne yüzünden ..., sonra iki saniye sürdü, cidden.'::text,'stres yapıp durmuştu'::text,'stres yapıp duruyor'::text,'stres yapıyordu'::text,'Yalan yok, kanka bütün hafta o iğne yüzünden stres yapıp durmuştu, sonra iki saniye sürdü, cidden.'::text),
(362025,40225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, a haverom egész héten ... az injekció miatt, aztán két másodperc volt az egész, komolyan.'::text,'parázott'::text,'parázik'::text,'parázott'::text,'Nem kamu, a haverom egész héten parázott az injekció miatt, aztán két másodperc volt az egész, komolyan.'::text),
(362028,40226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bis zum Mittag ... er seine Spritze hinter sich, und dann wird er angeben, echt.'::text,'hat'::text,'hat'::text,'bekommt'::text,'Yo, bis zum Mittag hat er seine Spritze hinter sich, und dann wird er angeben, echt.'::text),
(362032,40226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, до обіду він уже ... свій укол, і буде хизуватися, реально.'::text,'отримає'::text,'отримає'::text,'отримуватиме'::text,'Йо, до обіду він уже отримає свій укол, і буде хизуватися, реально.'::text),
(362031,40226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, para la hora de comer ya ... su inyección y va a presumir, en serio.'::text,'se habrá puesto'::text,'se pondrá'::text,'se estará poniendo'::text,'Oye, para la hora de comer ya se habrá puesto su inyección y va a presumir, en serio.'::text),
(362030,40226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, d''ici midi, il ... sa piqûre, et il va frimer, grave.'::text,'aura eu'::text,'aura'::text,'sera en train d''avoir'::text,'Yo, d''ici midi, il aura eu sa piqûre, et il va frimer, grave.'::text),
(362033,40226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, öğlene kadar iğnesini ... ve hava atacak, cidden.'::text,'olmuş olacak'::text,'olacak'::text,'oluyor olacak'::text,'Yo, öğlene kadar iğnesini olmuş olacak ve hava atacak, cidden.'::text),
(362034,40226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyi, ebédre már ... az injekcióját, és villogni fog, tényleg.'::text,'megkapja'::text,'megkapja'::text,'kapja'::text,'Figyi, ebédre már megkapja az injekcióját, és villogni fog, tényleg.'::text),
(362037,40227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Geschäftsschluss wird die Klinik acht Stunden lang Spritzen ..., ganz nach Plan.'::text,'gegeben haben'::text,'geben'::text,'gegeben haben'::text,'Bis Geschäftsschluss wird die Klinik acht Stunden lang Spritzen gegeben haben, ganz nach Plan.'::text),
(362041,40227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До закриття клініка ... уколи вісім годин, повністю за планом.'::text,'робитиме'::text,'робитиме'::text,'зробить'::text,'До закриття клініка робитиме уколи вісім годин, повністю за планом.'::text),
(362040,40227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de cierre, la clínica ... inyecciones durante ocho horas, totalmente según lo previsto.'::text,'habrá estado poniendo'::text,'estará poniendo'::text,'habrá puesto'::text,'Para la hora de cierre, la clínica habrá estado poniendo inyecciones durante ocho horas, totalmente según lo previsto.'::text),
(362039,40227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fermeture, la clinique ... des injections pendant huit heures, parfaitement dans les objectifs.'::text,'aura fait'::text,'fera'::text,'aura fait'::text,'D''ici la fermeture, la clinique aura fait des injections pendant huit heures, parfaitement dans les objectifs.'::text),
(362042,40227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapanış saatine kadar klinik sekiz saat boyunca iğne ..., tamamen hedefte.'::text,'yapmış olacak'::text,'yapıyor olacak'::text,'yapmış olacak'::text,'Kapanış saatine kadar klinik sekiz saat boyunca iğne yapmış olacak, tamamen hedefte.'::text),
(362043,40227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zárásig a klinika nyolc órán át ... az injekciókat, teljesen a terv szerint.'::text,'fogja adni'::text,'fogja adni'::text,'fogja beadni'::text,'Zárásig a klinika nyolc órán át fogja adni az injekciókat, teljesen a terv szerint.'::text),
(362046,40228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er Angst vor der Spritze gehabt hätte, ... er danach nicht seine Muskeln gezeigt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er Angst vor der Spritze gehabt hätte, hätte er danach nicht seine Muskeln gezeigt.'::text),
(362050,40228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він боявся уколу, він потім ... біцепсом.'::text,'не хизувався б'::text,'не хизуватиметься'::text,'не хизувався'::text,'Якби він боявся уколу, він потім не хизувався б біцепсом.'::text),
(362049,40228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le hubiera dado miedo la inyección, ... el brazo después.'::text,'no habría flexionado'::text,'no flexionará'::text,'no flexionó'::text,'Si le hubiera dado miedo la inyección, no habría flexionado el brazo después.'::text),
(362048,40228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait eu peur de la piqûre, il ... ses muscles après.'::text,'n''aurait pas montré'::text,'ne montrera pas'::text,'n''a pas montré'::text,'S''il avait eu peur de la piqûre, il n''aurait pas montré ses muscles après.'::text),
(362051,40228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İğneden korksaydı, sonrasında pazısını ...'::text,'kasmazdı'::text,'kasmayacak'::text,'kasmadı'::text,'İğneden korksaydı, sonrasında pazısını kasmazdı.'::text),
(362052,40228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha félt volna az injekciótól, utána ... a karját.'::text,'nem feszítette volna meg'::text,'nem fogja megfeszíteni'::text,'nem feszítette meg'::text,'Ha félt volna az injekciótól, utána nem feszítette volna meg a karját.'::text),
(362055,40229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Spritze ausgelassen hätte, ... er jetzt nicht so stolz.'::text,'wäre'::text,'wäre'::text,'ist'::text,'Wenn er die Spritze ausgelassen hätte, wäre er jetzt nicht so stolz.'::text),
(362059,40229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він пропустив укол, він зараз ... таким гордим.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби він пропустив укол, він зараз не був би таким гордим.'::text),
(362058,40229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se hubiera saltado la inyección, ahora ... tan orgulloso.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si se hubiera saltado la inyección, ahora no estaría tan orgulloso.'::text),
(362057,40229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait zappé la piqûre, il ... aussi fier maintenant.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'S''il avait zappé la piqûre, il ne serait pas aussi fier maintenant.'::text),
(362060,40229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İğneyi atlasaydı, şimdi bu kadar gururlu ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'İğneyi atlasaydı, şimdi bu kadar gururlu olmazdı.'::text),
(362061,40229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kihagyta volna az injekciót, most ... ilyen büszke.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha kihagyta volna az injekciót, most nem lenne ilyen büszke.'::text),
(362064,40230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man nimmt an, dass die Spritze fast gar keine Schmerzen ...'::text,'verursacht hat'::text,'verursacht'::text,'verursachend'::text,'Man nimmt an, dass die Spritze fast gar keine Schmerzen verursacht hat.'::text),
(362068,40230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що укол ... майже жодного болю.'::text,'спричинив'::text,'спричиняє'::text,'спричиняючи'::text,'Вважається, що укол спричинив майже жодного болю.'::text),
(362067,40230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la inyección ... casi nada de dolor.'::text,'causó'::text,'causa'::text,'causando'::text,'Se cree que la inyección causó casi nada de dolor.'::text),
(362066,40230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que l''injection ... presque aucune douleur.'::text,'a causé'::text,'cause'::text,'causant'::text,'On pense que l''injection a causé presque aucune douleur.'::text),
(362069,40230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İğnenin neredeyse hiç acı ... düşünülüyor.'::text,'vermediği'::text,'vermediği'::text,'vermeyen'::text,'İğnenin neredeyse hiç acı vermediği düşünülüyor.'::text),
(362070,40230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az injekció szinte semmilyen fájdalmat ...'::text,'nem okozott'::text,'nem okoz'::text,'nem okozva'::text,'Úgy tartják, hogy az injekció szinte semmilyen fájdalmat nem okozott.'::text),
(362073,40231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Krankenschwester riet ihm, seinen Arm während der Spritze ruhig zu ...'::text,'halten'::text,'halten'::text,'halten'::text,'Die Krankenschwester riet ihm, seinen Arm während der Spritze ruhig zu halten.'::text),
(362077,40231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра порадила йому ... руку нерухомо під час уколу.'::text,'тримати'::text,'тримати'::text,'тримати'::text,'Медсестра порадила йому тримати руку нерухомо під час уколу.'::text),
(362076,40231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enfermera le aconsejó ... el brazo quieto durante la inyección.'::text,'mantener'::text,'mantener'::text,'mantener'::text,'La enfermera le aconsejó mantener el brazo quieto durante la inyección.'::text),
(362075,40231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière lui a conseillé de ... son bras immobile pendant l''injection.'::text,'garder'::text,'garder'::text,'garder'::text,'L''infirmière lui a conseillé de garder son bras immobile pendant l''injection.'::text),
(362078,40231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire ona iğne sırasında kolunu sabit ... tavsiye etti.'::text,'tutmasını'::text,'tutmasını'::text,'tut'::text,'Hemşire ona iğne sırasında kolunu sabit tutmasını tavsiye etti.'::text),
(362079,40231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ápolónő azt tanácsolta neki, hogy ... mozdulatlanul a karját az injekció alatt.'::text,'tartsa'::text,'tartsa'::text,'tartsa'::text,'Az ápolónő azt tanácsolta neki, hogy tartsa mozdulatlanul a karját az injekció alatt.'::text),
(362091,40233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaum ... die Spritze begonnen, als er zu lächeln anfing.'::text,'hatte'::text,NULL::text,'war'::text,'Kaum hatte die Spritze begonnen, als er zu lächeln anfing.'::text),
(362095,40233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ледве ... укол почався, як він почав усміхатися.'::text,''::text,NULL::text,'був'::text,'Ледве укол почався, як він почав усміхатися.'::text),
(362094,40233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apenas ... empezado la inyección cuando él empezó a sonreír.'::text,'había'::text,NULL::text,'estaba'::text,'Apenas había empezado la inyección cuando él empezó a sonreír.'::text),
(362093,40233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À peine l''injection ... commencé qu''il s''est mis à sourire.'::text,'avait-elle'::text,NULL::text,'était-elle'::text,'À peine l''injection avait-elle commencé qu''il s''est mis à sourire.'::text),
(362096,40233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İğne daha yeni ... başlamıştı ki gülümsemeye başladı.'::text,''::text,NULL::text,NULL::text,'İğne daha yeni başlamıştı ki gülümsemeye başladı.'::text),
(362097,40233,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alig ... elkezdődött az injekció, amikor mosolyogni kezdett.'::text,''::text,NULL::text,'volt'::text,'Alig elkezdődött az injekció, amikor mosolyogni kezdett.'::text),
(362100,40234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Held, ganz klar: Er ließ die Krankenschwester die Spritze in unter fünf Sekunden ...'::text,'geben'::text,'geben'::text,'gebend'::text,'Ein echter Held, ganz klar: Er ließ die Krankenschwester die Spritze in unter fünf Sekunden geben.'::text),
(362104,40234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній герой, звісно: він змусив медсестру ... укол менш ніж за п''ять секунд.'::text,'зробити'::text,'зробити'::text,'роблячи'::text,'Справжній герой, звісно: він змусив медсестру зробити укол менш ніж за п''ять секунд.'::text),
(362103,40234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un héroe, obviamente: consiguió que la enfermera le ... la inyección en menos de cinco segundos.'::text,'pusiera'::text,'pusiera'::text,'poniendo'::text,'Todo un héroe, obviamente: consiguió que la enfermera le pusiera la inyección en menos de cinco segundos.'::text),
(362102,40234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai héros, évidemment : il a fait ... la piqûre par l''infirmière en moins de cinq secondes.'::text,'faire'::text,'faire'::text,'faisant'::text,'Un vrai héros, évidemment : il a fait faire la piqûre par l''infirmière en moins de cinq secondes.'::text),
(362105,40234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir kahraman, belli: hemşireye iğneyi beş saniyeden kısa sürede ...'::text,'yaptırdı'::text,'yaptırdı'::text,'yaparak'::text,'Gerçek bir kahraman, belli: hemşireye iğneyi beş saniyeden kısa sürede yaptırdı.'::text),
(362106,40234,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi hős, nyilván: elérte, hogy az ápolónő öt másodpercen belül ... neki az injekciót.'::text,'beadja'::text,'beadja'::text,'beadva'::text,'Igazi hős, nyilván: elérte, hogy az ápolónő öt másodpercen belül beadja neki az injekciót.'::text),
(400251,44473,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... sie Wasser in die Vase, also war die Vase nicht leer.'::text,'goss'::text,'goss'::text,'gießt'::text,'In diesem Moment goss sie Wasser in die Vase, also war die Vase nicht leer.'::text),
(400255,44473,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У той момент вона ... воду у вазу, тож ваза не була порожня.'::text,'наливала'::text,'налила'::text,'налила'::text,'У той момент вона наливала воду у вазу, тож ваза не була порожня.'::text),
(400254,44473,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ese momento ... agua en el jarrón, así que el jarrón no estaba vacío.'::text,'estaba echando'::text,'echó'::text,'ha echado'::text,'En ese momento estaba echando agua en el jarrón, así que el jarrón no estaba vacío.'::text),
(400253,44473,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À ce moment-là, elle ... de l''eau dans le vase, donc le vase n''était pas vide.'::text,'versait'::text,'a versé'::text,'a versé'::text,'À ce moment-là, elle versait de l''eau dans le vase, donc le vase n''était pas vide.'::text),
(400256,44473,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O anda vazoya su ..., yani vazo boş değildi.'::text,'döküyordu'::text,'döktü'::text,'dökmüş'::text,'O anda vazoya su döküyordu, yani vazo boş değildi.'::text),
(400257,44473,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a pillanatban éppen vizet ... a vázába, szóval a váza nem volt üres.'::text,'töltött'::text,'töltött'::text,'töltött'::text,'Abban a pillanatban éppen vizet töltött a vázába, szóval a váza nem volt üres.'::text),
(400269,44475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade Gänseblümchen in die Vase, als du dich plötzlich vorgebeugt hast, um daran zu riechen. Charmant.'::text,'stecktest'::text,'stecktest'::text,'steckst'::text,'Du stecktest gerade Gänseblümchen in die Vase, als du dich plötzlich vorgebeugt hast, um daran zu riechen. Charmant.'::text),
(400273,44475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... ромашки у вазу, коли раптом нахилилася, щоб їх понюхати. Чарівно.'::text,'ставила'::text,'поставила'::text,'поставила'::text,'Ти ставила ромашки у вазу, коли раптом нахилилася, щоб їх понюхати. Чарівно.'::text),
(400272,44475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... margaritas en el jarrón cuando de repente te inclinaste para olerlas. Encantador.'::text,'Estabas poniendo'::text,'Pusiste'::text,'Has puesto'::text,'Estabas poniendo margaritas en el jarrón cuando de repente te inclinaste para olerlas. Encantador.'::text),
(400271,44475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... des marguerites dans le vase quand tu t''es soudain penchée pour les sentir. Craquant.'::text,'mettais'::text,'as mis'::text,'as mis'::text,'Tu mettais des marguerites dans le vase quand tu t''es soudain penchée pour les sentir. Craquant.'::text),
(400274,44475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vazoya papatyaları ... ki birden koklamak için eğildin. Çok tatlı.'::text,'koyuyordun'::text,'koydun'::text,'koydun'::text,'Vazoya papatyaları koyuyordun ki birden koklamak için eğildin. Çok tatlı.'::text),
(400275,44475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen százszorszépeket ... a vázába, amikor hirtelen odahajoltál, hogy megszagold őket. Elbűvölő.'::text,'tettél'::text,'tettél'::text,'tettél'::text,'Éppen százszorszépeket tettél a vázába, amikor hirtelen odahajoltál, hogy megszagold őket. Elbűvölő.'::text),
(400278,44476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat bisher fünf Blumen in die Vase ...'::text,'gesteckt'::text,'gesteckt'::text,'gesteckt'::text,'Sie hat bisher fünf Blumen in die Vase gesteckt.'::text),
(400282,44476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі вона ... у вазу п''ять квітів.'::text,'поставила'::text,'ставить'::text,'поставила'::text,'Досі вона поставила у вазу п''ять квітів.'::text),
(400281,44476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... cinco flores en el jarrón.'::text,'ha puesto'::text,'ha estado poniendo'::text,'puso'::text,'Hasta ahora ha puesto cinco flores en el jarrón.'::text),
(400280,44476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pour l''instant, elle ... cinq fleurs dans le vase.'::text,'a mis'::text,'met'::text,'a mis'::text,'Pour l''instant, elle a mis cinq fleurs dans le vase.'::text),
(400283,44476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar vazoya beş çiçek ...'::text,'koydu'::text,'koyuyor'::text,'koydu'::text,'Şimdiye kadar vazoya beş çiçek koydu.'::text),
(400284,44476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig öt virágot ... a vázába.'::text,'tett'::text,'rakosgat'::text,'tett'::text,'Eddig öt virágot tett a vázába.'::text),
(400287,44477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie Blumen dazugab, ... sie Wasser in die Vase gegossen.'::text,'hatte'::text,'hat'::text,'gießt'::text,'Bevor sie Blumen dazugab, hatte sie Wasser in die Vase gegossen.'::text),
(400291,44477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж додати квіти, вона ... воду у вазу.'::text,'налила'::text,'налила'::text,'наливає'::text,'Перш ніж додати квіти, вона налила воду у вазу.'::text),
(400290,44477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de añadir flores, ... agua en el jarrón.'::text,'había echado'::text,'ha echado'::text,'echa'::text,'Antes de añadir flores, había echado agua en el jarrón.'::text),
(400289,44477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant d''ajouter des fleurs, elle ... de l''eau dans le vase.'::text,'avait versé'::text,'a versé'::text,'verse'::text,'Avant d''ajouter des fleurs, elle avait versé de l''eau dans le vase.'::text),
(400292,44477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçek eklemeden önce vazoya su ...'::text,'dökmüştü'::text,'döktü'::text,'döküyor'::text,'Çiçek eklemeden önce vazoya su dökmüştü.'::text),
(400293,44477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt virágot tett bele, vizet ... a vázába.'::text,'töltött'::text,'töltött'::text,'tölt'::text,'Mielőtt virágot tett bele, vizet töltött a vázába.'::text),
(400296,44478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch eine Sonnenblume dazugibt, ... die Vase zu voll.'::text,'wird'::text,'wäre'::text,'war'::text,'Wenn sie noch eine Sonnenblume dazugibt, wird die Vase zu voll.'::text),
(400300,44478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона додасть ще один соняшник, ваза ... занадто повна.'::text,'буде'::text,'була б'::text,'була'::text,'Якщо вона додасть ще один соняшник, ваза буде занадто повна.'::text),
(400299,44478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si añade un girasol más, el jarrón ... demasiado lleno.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si añade un girasol más, el jarrón estará demasiado lleno.'::text),
(400298,44478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ajoute encore un tournesol, le vase ... trop plein.'::text,'sera'::text,'serait'::text,'était'::text,'Si elle ajoute encore un tournesol, le vase sera trop plein.'::text),
(400301,44478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir ayçiçeği daha eklerse, vazo fazla dolu ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Bir ayçiçeği daha eklerse, vazo fazla dolu olacak.'::text),
(400302,44478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy napraforgót tesz bele, a váza túl tele ...'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha még egy napraforgót tesz bele, a váza túl tele lesz.'::text),
(400305,44479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns: Die Vase ... angeblich vor Jahren von ihrer Oma gemacht.'::text,'wurde'::text,'hat'::text,'machend'::text,'Unter uns: Die Vase wurde angeblich vor Jahren von ihrer Oma gemacht.'::text),
(400309,44479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, ця ваза ... її бабусею багато років тому, кажуть.'::text,'була зроблена'::text,'зробила'::text,'виготовлення'::text,'Між нами, ця ваза була зроблена її бабусею багато років тому, кажуть.'::text),
(400308,44479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotras, ese jarrón ... por su abuela hace años, al parecer.'::text,'fue hecho'::text,'hizo'::text,'haciendo'::text,'Entre nosotras, ese jarrón fue hecho por su abuela hace años, al parecer.'::text),
(400307,44479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, ce vase ... par sa grand-mère il y a des années, apparemment.'::text,'a été fait'::text,'a fait'::text,'faisant'::text,'Entre nous, ce vase a été fait par sa grand-mère il y a des années, apparemment.'::text),
(400310,44479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, o vazo yıllar önce büyükannesi tarafından ..., galiba.'::text,'yapılmış'::text,'yapmış'::text,'yapma'::text,'Aramızda kalsın, o vazo yıllar önce büyükannesi tarafından yapılmış, galiba.'::text),
(400311,44479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztünk szólva, azt a vázát állítólag a nagymamája ... évekkel ezelőtt.'::text,'készítette'::text,'készítette'::text,'készítés'::text,'Köztünk szólva, azt a vázát állítólag a nagymamája készítette évekkel ezelőtt.'::text),
(400314,44480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, sie ... die Vase wohl lieben, weil sie ewig an den Blumen gerochen hat.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Hör mal, sie muss die Vase wohl lieben, weil sie ewig an den Blumen gerochen hat.'::text),
(400318,44480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... любити ту вазу, бо цілу вічність нюхала квіти.'::text,'мусить'::text,'не може'::text,'повинна'::text,'Слухай, кажуть, вона мусить любити ту вазу, бо цілу вічність нюхала квіти.'::text),
(400317,44480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... adorar ese jarrón, porque estuvo oliendo las flores una eternidad.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Oye, al parecer debe de adorar ese jarrón, porque estuvo oliendo las flores una eternidad.'::text),
(400316,44480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... adorer ce vase, parce qu''elle a senti les fleurs pendant des heures.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Écoute, apparemment elle doit adorer ce vase, parce qu''elle a senti les fleurs pendant des heures.'::text),
(400319,44480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anlaşılan o vazoyu ..., çünkü çiçekleri saatlerce kokladı.'::text,'seviyor olmalı'::text,'seviyor olamaz'::text,'sevmeli'::text,'Dinle, anlaşılan o vazoyu seviyor olmalı, çünkü çiçekleri saatlerce kokladı.'::text),
(400320,44480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, úgy tűnik, ... imádja azt a vázát, mert órákig szagolgatta a virágokat.'::text,'biztosan'::text,'nem lehet, hogy'::text,'kellene, hogy'::text,'Figyelj, úgy tűnik, biztosan imádja azt a vázát, mert órákig szagolgatta a virágokat.'::text),
(400323,44481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Vase, in ... sie die Sonnenblumen gesteckt hat, ist schon ziemlich ikonisch.'::text,'die'::text,'wer'::text,'wo'::text,'Yo, die Vase, in die sie die Sonnenblumen gesteckt hat, ist schon ziemlich ikonisch.'::text),
(400327,44481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ваза, у ... вона поставила соняшники, доволі культова.'::text,'яку'::text,'кого'::text,'де'::text,'Йо, ваза, у яку вона поставила соняшники, доволі культова.'::text),
(400326,44481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el jarrón en ... puso los girasoles es bastante icónico.'::text,'el que'::text,'quien'::text,'donde'::text,'Oye, el jarrón en el que puso los girasoles es bastante icónico.'::text),
(400325,44481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le vase dans ... elle a mis les tournesols est plutôt iconique.'::text,'lequel'::text,'qui'::text,'où'::text,'Yo, le vase dans lequel elle a mis les tournesols est plutôt iconique.'::text),
(400328,44481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... ayçiçeklerini koyduğu vazo baya ikonik.'::text,''::text,NULL::text,NULL::text,'Yo, ayçiçeklerini koyduğu vazo baya ikonik.'::text),
(400329,44481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyi, a váza, ... a napraforgókat tette, elég ikonikus.'::text,'amibe'::text,'aki'::text,'ahol'::text,'Figyi, a váza, amibe a napraforgókat tette, elég ikonikus.'::text),
(400332,44482,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie hat gesagt, sie ... die Vase am Tag davor gekauft, echt jetzt.'::text,'hatte'::text,'hat'::text,'kauft'::text,'Digga, sie hat gesagt, sie hatte die Vase am Tag davor gekauft, echt jetzt.'::text),
(400336,44482,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сказала, що ... ту вазу напередодні, реально.'::text,'купила'::text,'купила'::text,'купує'::text,'Бро, вона сказала, що купила ту вазу напередодні, реально.'::text),
(400335,44482,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dijo que ... ese jarrón el día anterior, en serio.'::text,'había comprado'::text,'ha comprado'::text,'compra'::text,'Bro, dijo que había comprado ese jarrón el día anterior, en serio.'::text),
(400334,44482,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle a dit qu''elle ... ce vase la veille, sans mentir.'::text,'avait acheté'::text,'a acheté'::text,'achète'::text,'Frérot, elle a dit qu''elle avait acheté ce vase la veille, sans mentir.'::text),
(400337,44482,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o vazoyu bir gün önce ... söyledi, cidden.'::text,'aldığını'::text,'aldığını'::text,'alıyor'::text,'Kanka, o vazoyu bir gün önce aldığını söyledi, cidden.'::text),
(400338,44482,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy előző nap ... azt a vázát, komolyan.'::text,'vette meg'::text,'vette meg'::text,'veszi meg'::text,'Tesó, azt mondta, hogy előző nap vette meg azt a vázát, komolyan.'::text),
(330987,36777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... in absolutem Horror auf die Genehmigung, als die Beamtin endlich nach dem Aufkleber griff!'::text,'wartete'::text,'wartete'::text,'wartet'::text,'Er wartete in absolutem Horror auf die Genehmigung, als die Beamtin endlich nach dem Aufkleber griff!'::text),
(330991,36777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... схвалення в абсолютному жаху, коли службовиця нарешті потягнулася по наліпку!'::text,'чекав'::text,'дочекався'::text,'дочекався'::text,'Він чекав схвалення в абсолютному жаху, коли службовиця нарешті потягнулася по наліпку!'::text),
(330990,36777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... la aprobación con auténtico terror cuando la funcionaria por fin alcanzó la pegatina!'::text,'Estaba esperando'::text,'Esperó'::text,'Ha esperado'::text,'¡Estaba esperando la aprobación con auténtico terror cuando la funcionaria por fin alcanzó la pegatina!'::text),
(330989,36777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''approbation dans une terreur absolue quand l''employée a enfin attrapé l''autocollant !'::text,'attendait'::text,'a attendu'::text,'a attendu'::text,'Il attendait l''approbation dans une terreur absolue quand l''employée a enfin attrapé l''autocollant !'::text),
(330992,36777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur sonunda etikete uzandığında o, mutlak bir dehşet içinde onay ...!'::text,'bekliyordu'::text,'bekledi'::text,'bekledi'::text,'Memur sonunda etikete uzandığında o, mutlak bir dehşet içinde onay bekliyordu!'::text),
(330993,36777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljes rettegésben ... a jóváhagyásra, amikor az ügyintéző végre a matricáért nyúlt!'::text,'várt'::text,'várt'::text,'várt'::text,'Teljes rettegésben várt a jóváhagyásra, amikor az ügyintéző végre a matricáért nyúlt!'::text),
(330996,36778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit dem frühen Morgen auf die Genehmigung seines Visums.'::text,'wartet'::text,'wartet'::text,'wartet'::text,'Er wartet seit dem frühen Morgen auf die Genehmigung seines Visums.'::text),
(331000,36778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... схвалення своєї візи з самого ранку.'::text,'чекає'::text,'чекає'::text,'чекає'::text,'Він чекає схвалення своєї візи з самого ранку.'::text),
(330999,36778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la aprobación de su visado desde primera hora de la mañana.'::text,'Lleva esperando'::text,'Está esperando'::text,'Espera'::text,'Lleva esperando la aprobación de su visado desde primera hora de la mañana.'::text),
(330998,36778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''approbation de son visa depuis tôt ce matin.'::text,'attend'::text,'attend'::text,'attend'::text,'Il attend l''approbation de son visa depuis tôt ce matin.'::text),
(331001,36778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabahın erken saatlerinden beri vizesinin onayını ...'::text,'bekliyor'::text,'bekliyor'::text,'bekler'::text,'Sabahın erken saatlerinden beri vizesinin onayını bekliyor.'::text),
(331002,36778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kora reggel óta ... a vízuma jóváhagyására.'::text,'vár'::text,'vár'::text,'vár'::text,'Kora reggel óta vár a vízuma jóváhagyására.'::text),
(331005,36779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Beamtin ... gerade seine Papiere, als er anfing, sich wegen der Genehmigung Sorgen zu machen.'::text,'las'::text,'las'::text,'las'::text,'Die Beamtin las gerade seine Papiere, als er anfing, sich wegen der Genehmigung Sorgen zu machen.'::text),
(331009,36779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Службовиця ... його документи, коли він почав хвилюватися через схвалення.'::text,'читала'::text,'прочитала'::text,'прочитала'::text,'Службовиця читала його документи, коли він почав хвилюватися через схвалення.'::text),
(331008,36779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La funcionaria ... sus papeles cuando él empezó a preocuparse por la aprobación.'::text,'estaba leyendo'::text,'leyó'::text,'ha leído'::text,'La funcionaria estaba leyendo sus papeles cuando él empezó a preocuparse por la aprobación.'::text),
(331007,36779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''employée ... ses papiers quand il a commencé à s''inquiéter pour l''approbation.'::text,'lisait'::text,'a lu'::text,'a lu'::text,'L''employée lisait ses papiers quand il a commencé à s''inquiéter pour l''approbation.'::text),
(331010,36779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onay için endişelenmeye başladığında memur onun evraklarını ...'::text,'okuyordu'::text,'okudu'::text,'okudu'::text,'Onay için endişelenmeye başladığında memur onun evraklarını okuyordu.'::text),
(331011,36779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyintéző éppen a papírjait ..., amikor aggódni kezdett a jóváhagyás miatt.'::text,'olvasta'::text,'elolvasta'::text,'elolvasta'::text,'Az ügyintéző éppen a papírjait olvasta, amikor aggódni kezdett a jóváhagyás miatt.'::text),
(331014,36780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat dieses Jahr die Genehmigung für drei Visa ...'::text,'bekommen'::text,'bekommen'::text,'bekommen'::text,'Er hat dieses Jahr die Genehmigung für drei Visa bekommen.'::text),
(331018,36780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього року він ... схвалення трьох віз.'::text,'отримав'::text,'отримував'::text,'отримав'::text,'Цього року він отримав схвалення трьох віз.'::text),
(331017,36780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este año ... la aprobación de tres visados.'::text,'ha recibido'::text,'ha estado recibiendo'::text,'recibió'::text,'Este año ha recibido la aprobación de tres visados.'::text),
(331016,36780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette année, il ... l''approbation pour trois visas.'::text,'a reçu'::text,'reçoit'::text,'a reçu'::text,'Cette année, il a reçu l''approbation pour trois visas.'::text),
(331019,36780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yıl üç vize için onay ...'::text,'aldı'::text,'alıyor'::text,'aldı'::text,'Bu yıl üç vize için onay aldı.'::text),
(331020,36780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Idén három vízumra ... jóváhagyást.'::text,'kapott'::text,'kapott'::text,'kapott'::text,'Idén három vízumra kapott jóváhagyást.'::text),
(331032,36782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er braucht ... des Amts, bevor er reisen kann.'::text,'die Genehmigung'::text,'eine Genehmigung'::text,'die Genehmigungen'::text,'Er braucht die Genehmigung des Amts, bevor er reisen kann.'::text),
(331036,36782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому потрібне ... відомства, перш ніж він зможе подорожувати.'::text,'схвалення'::text,'схвалення'::text,'схвалення'::text,'Йому потрібне схвалення відомства, перш ніж він зможе подорожувати.'::text),
(331035,36782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Necesita ... de la oficina antes de poder viajar.'::text,'la aprobación'::text,'una aprobación'::text,'las aprobaciones'::text,'Necesita la aprobación de la oficina antes de poder viajar.'::text),
(331034,36782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il lui faut ... du bureau avant de pouvoir voyager.'::text,'l''approbation'::text,'une approbation'::text,'les approbations'::text,'Il lui faut l''approbation du bureau avant de pouvoir voyager.'::text),
(331037,36782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seyahat edebilmek için ofisin ... ihtiyacı var.'::text,'onayına'::text,'bir onaya'::text,'onaylarına'::text,'Seyahat edebilmek için ofisin onayına ihtiyacı var.'::text),
(331038,36782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szüksége van ... a hivataltól, mielőtt utazhat.'::text,'a jóváhagyásra'::text,'egy jóváhagyásra'::text,'a jóváhagyásokra'::text,'Szüksége van a jóváhagyásra a hivataltól, mielőtt utazhat.'::text),
(331041,36783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Genehmigung kann die Reise wie geplant am 1. Juni stattfinden.'::text,'Nach'::text,'Trotz'::text,'Im Falle'::text,'Nach der Genehmigung kann die Reise wie geplant am 1. Juni stattfinden.'::text),
(331045,36783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... схвалення поїздка може відбутися 1 червня, як і планувалося.'::text,'Після'::text,'Попри'::text,'У разі'::text,'Після схвалення поїздка може відбутися 1 червня, як і планувалося.'::text),
(331044,36783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la aprobación, el viaje puede realizarse el 1 de junio según lo previsto.'::text,'Tras'::text,'Pese a'::text,'En caso de'::text,'Tras la aprobación, el viaje puede realizarse el 1 de junio según lo previsto.'::text),
(331043,36783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''approbation, le voyage peut avoir lieu le 1er juin comme prévu.'::text,'Suite à'::text,'Malgré'::text,'En cas de'::text,'Suite à l''approbation, le voyage peut avoir lieu le 1er juin comme prévu.'::text),
(331046,36783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onayın ..., gezi planlandığı gibi 1 Haziran''da yapılabilir.'::text,'ardından'::text,'rağmen'::text,'durumunda'::text,'Onayın ardından, gezi planlandığı gibi 1 Haziran''da yapılabilir.'::text),
(331047,36783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jóváhagyás ... az utazás a tervek szerint június 1-jén megvalósulhat.'::text,'után'::text,'ellenére'::text,'esetén'::text,'A jóváhagyás után az utazás a tervek szerint június 1-jén megvalósulhat.'::text),
(331050,36784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wusste, dass die Genehmigung seinen ganzen Sommer ...'::text,'verändern würde'::text,'verändern wird'::text,'verändert'::text,'Er wusste, dass die Genehmigung seinen ganzen Sommer verändern würde.'::text),
(331054,36784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він знав, що схвалення ... все його літо.'::text,'змінить'::text,'змінить'::text,'змінює'::text,'Він знав, що схвалення змінить все його літо.'::text),
(331053,36784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que la aprobación ... todo su verano.'::text,'cambiaría'::text,'cambiará'::text,'cambia'::text,'Sabía que la aprobación cambiaría todo su verano.'::text),
(331052,36784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il savait que l''approbation ... tout son été.'::text,'changerait'::text,'changera'::text,'change'::text,'Il savait que l''approbation changerait tout son été.'::text),
(331055,36784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onayın bütün yazını ... biliyordu.'::text,'değiştireceğini'::text,'değiştireceğini'::text,'değiştirdiğini'::text,'Onayın bütün yazını değiştireceğini biliyordu.'::text),
(331056,36784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a jóváhagyás ... az egész nyarát.'::text,'megváltoztatja'::text,'meg fogja változtatni'::text,'megváltoztatja'::text,'Tudta, hogy a jóváhagyás megváltoztatja az egész nyarát.'::text),
(331059,36785,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, ... der Antragsteller auf die Genehmigung, während die Beamtin seinen Pass prüft.'::text,'wartet'::text,'wartet'::text,'wartete'::text,'Wie beobachtet, wartet der Antragsteller auf die Genehmigung, während die Beamtin seinen Pass prüft.'::text),
(331063,36785,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як спостерігається, заявник ... схвалення, поки службовиця перевіряє його паспорт.'::text,'чекає'::text,'чекає'::text,'чекав'::text,'Як спостерігається, заявник чекає схвалення, поки службовиця перевіряє його паспорт.'::text),
(331062,36785,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, el solicitante ... la aprobación mientras la funcionaria examina su pasaporte.'::text,'está esperando'::text,'espera'::text,'ha esperado'::text,'Según lo observado, el solicitante está esperando la aprobación mientras la funcionaria examina su pasaporte.'::text),
(331061,36785,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme observé, le demandeur ... l''approbation pendant que l''employée examine son passeport.'::text,'attend'::text,'attend'::text,'a attendu'::text,'Comme observé, le demandeur attend l''approbation pendant que l''employée examine son passeport.'::text),
(331064,36785,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere, memur pasaportunu incelerken başvuru sahibi onay ...'::text,'bekliyor'::text,'bekler'::text,'bekledi'::text,'Gözlemlendiği üzere, memur pasaportunu incelerken başvuru sahibi onay bekliyor.'::text),
(331065,36785,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megfigyelés szerint a kérelmező ... a jóváhagyásra, miközben az ügyintéző az útlevelét vizsgálja.'::text,'vár'::text,'vár'::text,'várt'::text,'Megfigyelés szerint a kérelmező vár a jóváhagyásra, miközben az ügyintéző az útlevelét vizsgálja.'::text),
(331077,36787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis morgen wird er seine Genehmigung absolut allen ...!'::text,'gezeigt haben'::text,'zeigen'::text,'zeigen'::text,'Bis morgen wird er seine Genehmigung absolut allen gezeigt haben!'::text),
(331081,36787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До завтра він ... своє схвалення абсолютно всім!'::text,'покаже'::text,'покаже'::text,'показує'::text,'До завтра він покаже своє схвалення абсолютно всім!'::text),
(331080,36787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para mañana ... su aprobación a absolutamente todo el mundo!'::text,'habrá enseñado'::text,'enseñará'::text,'enseña'::text,'¡Para mañana habrá enseñado su aprobación a absolutamente todo el mundo!'::text),
(331079,36787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici demain, il ... son approbation à absolument tout le monde !'::text,'aura montré'::text,'montrera'::text,'montre'::text,'D''ici demain, il aura montré son approbation à absolument tout le monde !'::text),
(331082,36787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarına kadar onayını kesinlikle herkese ...!'::text,'göstermiş olacak'::text,'gösterecek'::text,'gösteriyor'::text,'Yarına kadar onayını kesinlikle herkese göstermiş olacak!'::text),
(331083,36787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnapra ... a jóváhagyását abszolút mindenkinek!'::text,'megmutatja'::text,'megmutatja'::text,'mutatja'::text,'Holnapra megmutatja a jóváhagyását abszolút mindenkinek!'::text),
(400953,44551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie gerade in ihrer Küche wieder einen orangen Vitamindrink.'::text,'trinkt'::text,'trinkt'::text,'trinkt'::text,'Morgen um diese Zeit trinkt sie gerade in ihrer Küche wieder einen orangen Vitamindrink.'::text),
(400957,44551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... ще один помаранчевий вітамінний напій на своїй кухні.'::text,'питиме'::text,'вип''є'::text,'п''є'::text,'Завтра в цей час вона питиме ще один помаранчевий вітамінний напій на своїй кухні.'::text),
(400956,44551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra bebida naranja de vitaminas en su cocina.'::text,'estará bebiendo'::text,'beberá'::text,'bebe'::text,'Mañana a esta hora estará bebiendo otra bebida naranja de vitaminas en su cocina.'::text),
(400955,44551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... une autre boisson vitaminée orange dans sa cuisine.'::text,'sera en train de boire'::text,'boira'::text,'boit'::text,'Demain à la même heure, elle sera en train de boire une autre boisson vitaminée orange dans sa cuisine.'::text),
(400958,44551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde mutfağında bir başka turuncu vitamin içeceği ...'::text,'içiyor olacak'::text,'içecek'::text,'içer'::text,'Yarın bu saatlerde mutfağında bir başka turuncu vitamin içeceği içiyor olacak.'::text),
(400959,44551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a konyhájában egy újabb narancssárga vitaminitalt ...'::text,'fog inni'::text,'megiszik'::text,'iszik'::text,'Holnap ilyenkor a konyhájában egy újabb narancssárga vitaminitalt fog inni.'::text),
(400971,44553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Vitamintablette brausend ist, ... sie typischerweise, sobald sie Wasser berührt.'::text,'sprudelt'::text,'wird sprudeln'::text,'sprudelte'::text,'Wenn eine Vitamintablette brausend ist, sprudelt sie typischerweise, sobald sie Wasser berührt.'::text),
(400975,44553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вітамінна таблетка шипуча, вона зазвичай ..., коли торкається води.'::text,'шипить'::text,'шипітиме'::text,'шипіла'::text,'Якщо вітамінна таблетка шипуча, вона зазвичай шипить, коли торкається води.'::text),
(400974,44553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una pastilla de vitaminas es efervescente, normalmente ... al tocar el agua.'::text,'burbujea'::text,'burbujeará'::text,'burbujeó'::text,'Si una pastilla de vitaminas es efervescente, normalmente burbujea al tocar el agua.'::text),
(400973,44553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un comprimé de vitamines est effervescent, il ... généralement au contact de l''eau.'::text,'pétille'::text,'pétillera'::text,'a pétillé'::text,'Si un comprimé de vitamines est effervescent, il pétille généralement au contact de l''eau.'::text),
(400976,44553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir vitamin tableti efervesan ise, suya değdiğinde genellikle ...'::text,'köpürür'::text,'köpürecek'::text,'köpürdü'::text,'Bir vitamin tableti efervesan ise, suya değdiğinde genellikle köpürür.'::text),
(400977,44553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy vitamintabletta pezsgő, általában ..., amikor vízhez ér.'::text,'pezseg'::text,'pezsegni fog'::text,'pezsgett'::text,'Ha egy vitamintabletta pezsgő, általában pezseg, amikor vízhez ér.'::text),
(400980,44554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... Vitamine, ehrlich, aber jetzt trinkst du das Glas wie ein Profi.'::text,'hasstest früher'::text,'hasstest früher'::text,'warst es gewohnt zu hassen'::text,'Du hasstest früher Vitamine, ehrlich, aber jetzt trinkst du das Glas wie ein Profi.'::text),
(400984,44554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... вітаміни, чесно, але тепер п''єш ту склянку як профі.'::text,'раніше ненавиділа'::text,'раніше ненавиділа'::text,'звикла ненавидіти'::text,'Ти раніше ненавиділа вітаміни, чесно, але тепер п''єш ту склянку як профі.'::text),
(400983,44554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes ... las vitaminas, en serio, pero ahora te bebes ese vaso como una pro.'::text,'odiabas'::text,'odiabas'::text,'estabas acostumbrada a odiar'::text,'Antes odiabas las vitaminas, en serio, pero ahora te bebes ese vaso como una pro.'::text),
(400982,44554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, tu ... les vitamines, franchement, mais maintenant tu bois ce verre comme une pro.'::text,'détestais'::text,'détestais'::text,'avais l''habitude de détester'::text,'Avant, tu détestais les vitamines, franchement, mais maintenant tu bois ce verre comme une pro.'::text),
(400985,44554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası eskiden vitaminlerden ..., ama şimdi o bardağı profesyonel gibi içiyorsun.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Açıkçası eskiden vitaminlerden nefret ederdin, ama şimdi o bardağı profesyonel gibi içiyorsun.'::text),
(400986,44554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, régen ... a vitaminokat, most meg úgy iszod azt a poharat, mint egy profi.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva, hogy utáld'::text,'Őszintén, régen utáltad a vitaminokat, most meg úgy iszod azt a poharat, mint egy profi.'::text),
(400989,44555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es macht dir nichts aus, ein ganzes Glas Brausevitamin zu ...? Respekt.'::text,'trinken'::text,'trinken'::text,'trinken'::text,'Es macht dir nichts aus, ein ganzes Glas Brausevitamin zu trinken? Respekt.'::text),
(400993,44555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тобі не важко ... цілу склянку шипучого вітаміну? Респект.'::text,'випити'::text,'випити'::text,'випити'::text,'Тобі не важко випити цілу склянку шипучого вітаміну? Респект.'::text),
(400992,44555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿No te importa ... un vaso entero de vitamina efervescente? Respeto.'::text,'beberte'::text,'beberte'::text,'beberte'::text,'¿No te importa beberte un vaso entero de vitamina efervescente? Respeto.'::text),
(400991,44555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça ne te dérange pas de ... un verre entier de vitamine effervescente ? Respect.'::text,'boire'::text,'boire'::text,'boire'::text,'Ça ne te dérange pas de boire un verre entier de vitamine effervescente ? Respect.'::text),
(400994,44555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koca bir bardak köpüren vitamini ... sorun değil mi? Saygılar.'::text,'içmek'::text,'içmek'::text,'iç'::text,'Koca bir bardak köpüren vitamini içmek sorun değil mi? Saygılar.'::text),
(400995,44555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem zavar, hogy ... egy egész pohár pezsgő vitamint? Respekt.'::text,'megiszol'::text,'megiszol'::text,'megiszol'::text,'Nem zavar, hogy megiszol egy egész pohár pezsgő vitamint? Respekt.'::text),
(400998,44556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du liebst deinen orangen Vitamindrink, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Ehrlich gesagt, du liebst deinen orangen Vitamindrink, oder?'::text),
(401002,44556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти обожнюєш свій помаранчевий вітамінний напій, ...?'::text,'так'::text,'так'::text,'так'::text,'Чесно, ти обожнюєш свій помаранчевий вітамінний напій, так?'::text),
(401001,44556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, te encanta tu bebida naranja de vitaminas, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'No te voy a mentir, te encanta tu bebida naranja de vitaminas, ¿verdad?'::text),
(401000,44556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu adores ta boisson vitaminée orange, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Sans mentir, tu adores ta boisson vitaminée orange, pas vrai ?'::text),
(401003,44556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, turuncu vitamin içeceğini çok seviyorsun, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Yalan yok, turuncu vitamin içeceğini çok seviyorsun, değil mi?'::text),
(401004,44556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, imádod a narancssárga vitaminitalodat, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Nem kamu, imádod a narancssárga vitaminitalodat, ugye?'::text),
(401007,44557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Vitamintablette war offensichtlich begeistert zu sprudeln, und ...'::text,'sie auch'::text,'sie auch'::text,'sie auch'::text,'Die Vitamintablette war offensichtlich begeistert zu sprudeln, und sie auch.'::text),
(401011,44557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вітамінна таблетка явно була в захваті від того, що шипить, і ...'::text,'вона теж'::text,'вона теж'::text,'вона теж'::text,'Вітамінна таблетка явно була в захваті від того, що шипить, і вона теж.'::text),
(401010,44557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, la pastilla de vitaminas estaba encantada de burbujear, y ...'::text,'ella también'::text,'ella también'::text,'ella también'::text,'Obviamente, la pastilla de vitaminas estaba encantada de burbujear, y ella también.'::text),
(401009,44557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pastille de vitamines était visiblement ravie de pétiller, et ...'::text,'elle aussi'::text,'elle aussi'::text,'elle aussi'::text,'La pastille de vitamines était visiblement ravie de pétiller, et elle aussi.'::text),
(401012,44557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vitamin tableti köpürmekten belli ki çok mutluydu, ve ...'::text,'o da öyleydi'::text,'o da öyle yaptı'::text,'o da öyle'::text,'Vitamin tableti köpürmekten belli ki çok mutluydu, ve o da öyleydi.'::text),
(401013,44557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vitamintabletta nyilván odavolt a pezsgésért, és ...'::text,'ő is'::text,'ő is'::text,'ő is'::text,'A vitamintabletta nyilván odavolt a pezsgésért, és ő is.'::text),
(401016,44558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Monatsende ... sie die ganze Dose Vitamine aufgebraucht. Wahnsinnig spannend.'::text,'hat'::text,'hat'::text,'wird'::text,'Bis Monatsende hat sie die ganze Dose Vitamine aufgebraucht. Wahnsinnig spannend.'::text),
(401020,44558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця місяця вона ... цілу банку вітамінів. Справді захопливо.'::text,'вип''є'::text,'вип''є'::text,'питиме'::text,'До кінця місяця вона вип''є цілу банку вітамінів. Справді захопливо.'::text),
(401019,44558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para final de mes, ... todo el bote de vitaminas. Emocionantísimo.'::text,'se habrá terminado'::text,'se terminará'::text,'se estará terminando'::text,'Para final de mes, se habrá terminado todo el bote de vitaminas. Emocionantísimo.'::text),
(401018,44558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du mois, elle ... tout le pot de vitamines. Vraiment palpitant.'::text,'aura fini'::text,'finira'::text,'sera en train de finir'::text,'D''ici la fin du mois, elle aura fini tout le pot de vitamines. Vraiment palpitant.'::text),
(401021,44558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ay sonuna kadar bütün vitamin kavanozunu ..., gerçekten çok heyecan verici.'::text,'bitirmiş olacak'::text,'bitirecek'::text,'bitiriyor olacak'::text,'Ay sonuna kadar bütün vitamin kavanozunu bitirmiş olacak, gerçekten çok heyecan verici.'::text),
(401022,44558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hónap végére ... az egész doboz vitamint. Igazán izgalmas.'::text,'elfogyasztja'::text,'elfogyasztja'::text,'fogyasztja'::text,'A hónap végére elfogyasztja az egész doboz vitamint. Igazán izgalmas.'::text),
(401034,44560,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Vitamintablette ... im Glas, und das Wasser färbt sich orange.'::text,'sprudelt'::text,'sprudelt'::text,'sprudelte'::text,'Die Vitamintablette sprudelt im Glas, und das Wasser färbt sich orange.'::text),
(401038,44560,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вітамінна таблетка ... у склянці, і вода стає помаранчевою.'::text,'шипить'::text,'шипить'::text,'зашипіла'::text,'Вітамінна таблетка шипить у склянці, і вода стає помаранчевою.'::text),
(401037,44560,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pastilla de vitaminas ... en el vaso y el agua se está volviendo naranja.'::text,'está burbujeando'::text,'burbujea'::text,'ha burbujeado'::text,'La pastilla de vitaminas está burbujeando en el vaso y el agua se está volviendo naranja.'::text),
(401036,44560,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le comprimé de vitamines ... dans le verre, et l''eau devient orange.'::text,'pétille'::text,'pétille'::text,'a pétillé'::text,'Le comprimé de vitamines pétille dans le verre, et l''eau devient orange.'::text),
(401039,44560,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vitamin tableti bardakta ... ve su turuncuya dönüyor.'::text,'köpürüyor'::text,'köpürür'::text,'köpürdü'::text,'Vitamin tableti bardakta köpürüyor ve su turuncuya dönüyor.'::text),
(401040,44560,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vitamintabletta ... a pohárban, és a víz narancssárgává válik.'::text,'pezseg'::text,'pezseg'::text,'pezsgett'::text,'A vitamintabletta pezseg a pohárban, és a víz narancssárgává válik.'::text),
(401043,44561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Vitamintablette ins Glas geworfen, bevor sie das orange Wasser trank.'::text,'hatte'::text,'hat'::text,'hat'::text,'Sie hatte die Vitamintablette ins Glas geworfen, bevor sie das orange Wasser trank.'::text),
(401047,44561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... вітамінну таблетку в склянку, перш ніж випила помаранчеву воду.'::text,'кинула'::text,'кинула'::text,'кидала'::text,'Вона кинула вітамінну таблетку в склянку, перш ніж випила помаранчеву воду.'::text),
(401046,44561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la pastilla de vitaminas en el vaso antes de beberse el agua naranja.'::text,'Había echado'::text,'Ha echado'::text,'Estaba echando'::text,'Había echado la pastilla de vitaminas en el vaso antes de beberse el agua naranja.'::text),
(401045,44561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le comprimé de vitamines dans le verre avant de boire l''eau orange.'::text,'avait mis'::text,'a mis'::text,'mettait'::text,'Elle avait mis le comprimé de vitamines dans le verre avant de boire l''eau orange.'::text),
(401048,44561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turuncu suyu içmeden önce vitamin tabletini bardağa ...'::text,'atmıştı'::text,'attı'::text,'atıyordu'::text,'Turuncu suyu içmeden önce vitamin tabletini bardağa atmıştı.'::text),
(401049,44561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt megitta a narancssárga vizet, ... a vitamintablettát a pohárba.'::text,'bedobta'::text,'bedobta'::text,'dobta'::text,'Mielőtt megitta a narancssárga vizet, bedobta a vitamintablettát a pohárba.'::text),
(386832,42982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Teetassen ... sich im Kreis, als ihn die Übelkeit wie eine Katastrophe traf!'::text,'drehten'::text,'drehten'::text,'drehen'::text,'Die Teetassen drehten sich im Kreis, als ihn die Übelkeit wie eine Katastrophe traf!'::text),
(386836,42982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чашки ... по колу, коли нудота вдарила його, як катастрофа!'::text,'крутилися'::text,'покрутилися'::text,'покрутилися'::text,'Чашки крутилися по колу, коли нудота вдарила його, як катастрофа!'::text),
(386835,42982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las tazas ... sin parar cuando el mareo le golpeó como un desastre!'::text,'estaban girando'::text,'giraron'::text,'han girado'::text,'¡Las tazas estaban girando sin parar cuando el mareo le golpeó como un desastre!'::text),
(386834,42982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tasses ... en rond quand le malaise l''a frappé comme une catastrophe !'::text,'tournaient'::text,'ont tourné'::text,'ont tourné'::text,'Les tasses tournaient en rond quand le malaise l''a frappé comme une catastrophe !'::text),
(386837,42982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mide bulantısı onu bir felaket gibi vurduğunda fincanlar durmadan ...!'::text,'dönüyordu'::text,'döndü'::text,'döndü'::text,'Mide bulantısı onu bir felaket gibi vurduğunda fincanlar durmadan dönüyordu!'::text),
(386838,42982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A teáscsészék körbe-körbe ..., amikor a rosszullét katasztrófaként csapott le rá!'::text,'forogtak'::text,'pördültek'::text,'pördültek'::text,'A teáscsészék körbe-körbe forogtak, amikor a rosszullét katasztrófaként csapott le rá!'::text),
(386850,42984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... er gerade aus dem Fahrgeschäft, als ihn plötzlich die Übelkeit packte.'::text,'stieg'::text,'stieg'::text,'stieg'::text,'Mädel, anscheinend stieg er gerade aus dem Fahrgeschäft, als ihn plötzlich die Übelkeit packte.'::text),
(386854,42984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... з атракціону, коли його раптом накрила нудота.'::text,'сходив'::text,'зійшов'::text,'зійшов'::text,'Подруго, кажуть, він сходив з атракціону, коли його раптом накрила нудота.'::text),
(386853,42984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... de la atracción cuando de repente le dio el mareo.'::text,'estaba bajando'::text,'bajó'::text,'ha bajado'::text,'Tía, al parecer estaba bajando de la atracción cuando de repente le dio el mareo.'::text),
(386852,42984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... du manège quand le malaise l''a soudain pris.'::text,'descendait'::text,'est descendu'::text,'est descendu'::text,'Meuf, apparemment il descendait du manège quand le malaise l''a soudain pris.'::text),
(386855,42984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan mide bulantısı aniden bastırdığında o, oyuncaktan ...'::text,'iniyordu'::text,'indi'::text,'inmiş'::text,'Kızım, anlaşılan mide bulantısı aniden bastırdığında o, oyuncaktan iniyordu.'::text),
(386856,42984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag éppen ... a körhintáról, amikor hirtelen rosszul lett.'::text,'szállt le'::text,'leszállt'::text,'leszállt'::text,'Csajszi, állítólag éppen szállt le a körhintáról, amikor hirtelen rosszul lett.'::text),
(386859,42985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat zugegeben, zweimal mit den Teetassen ..., also war die Übelkeit seine eigene Schuld.'::text,'gefahren zu sein'::text,'zu fahren'::text,'fuhr'::text,'Bestie, er hat zugegeben, zweimal mit den Teetassen gefahren zu sein, also war die Übelkeit seine eigene Schuld.'::text),
(386863,42985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він зізнався, що ... на чашках двічі, тож нудота — його власна провина.'::text,'катався'::text,'покататися'::text,'покатався'::text,'Подруго, він зізнався, що катався на чашках двічі, тож нудота — його власна провина.'::text),
(386862,42985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, admitió ... en las tazas dos veces, así que el mareo fue culpa suya.'::text,'haberse montado'::text,'montarse'::text,'se montó'::text,'Amiga, admitió haberse montado en las tazas dos veces, así que el mareo fue culpa suya.'::text),
(386861,42985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il a avoué ... les tasses deux fois, donc le malaise, c''était de sa faute.'::text,'avoir fait'::text,'faire'::text,'a fait'::text,'Ma belle, il a avoué avoir fait les tasses deux fois, donc le malaise, c''était de sa faute.'::text),
(386864,42985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, fincanlara iki kez ... itiraf etti, yani mide bulantısı tamamen kendi suçu.'::text,'bindiğini'::text,'binmeyi'::text,'bindi'::text,'Kanka, fincanlara iki kez bindiğini itiraf etti, yani mide bulantısı tamamen kendi suçu.'::text),
(386865,42985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, bevallotta, hogy kétszer ... a csészékkel, szóval a rosszullét a saját hibája volt.'::text,'ment'::text,'megy'::text,'ment'::text,'Csajszi, bevallotta, hogy kétszer ment a csészékkel, szóval a rosszullét a saját hibája volt.'::text),
(386868,42986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh mein Gott, nach dem Mittagessen hätte er nicht in die Teetassen ..., ich hab gehört, die Übelkeit war furchtbar.'::text,'steigen sollen'::text,'steigen müssen'::text,'steigen können'::text,'Oh mein Gott, nach dem Mittagessen hätte er nicht in die Teetassen steigen sollen, ich hab gehört, die Übelkeit war furchtbar.'::text),
(386872,42986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, він ... на чашки після обіду. Я чула, що нудота була жахлива.'::text,'не мав іти'::text,'не мусив іти'::text,'не міг піти'::text,'Боже, він не мав іти на чашки після обіду. Я чула, що нудота була жахлива.'::text),
(386871,42986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios mío, ... a las tazas después de comer. Me han dicho que el mareo fue horrible.'::text,'no debería haber ido'::text,'no debe de haber ido'::text,'no pudo ir'::text,'Dios mío, no debería haber ido a las tazas después de comer. Me han dicho que el mareo fue horrible.'::text),
(386870,42986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh mon Dieu, il ... dans les tasses après le déjeuner. Il paraît que le malaise était horrible.'::text,'n''aurait pas dû monter'::text,'n''a pas dû monter'::text,'n''a pas pu monter'::text,'Oh mon Dieu, il n''aurait pas dû monter dans les tasses après le déjeuner. Il paraît que le malaise était horrible.'::text),
(386873,42986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, öğle yemeğinden sonra fincanlara ..., mide bulantısı berbatmış diye duydum.'::text,'binmemeliydi'::text,'binmemiş olmalı'::text,'binemedi'::text,'Aman tanrım, öğle yemeğinden sonra fincanlara binmemeliydi, mide bulantısı berbatmış diye duydum.'::text),
(386874,42986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, ebéd után ... a csészékre. Úgy hallottam, a rosszullét borzasztó volt.'::text,'nem kellett volna felülnie'::text,'biztos nem ült fel'::text,'nem tudott felülni'::text,'Úristen, ebéd után nem kellett volna felülnie a csészékre. Úgy hallottam, a rosszullét borzasztó volt.'::text),
(386886,42988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du wünschst dir, du ... nicht mit den Teetassen gefahren, aber mit der Übelkeit bist du echt tapfer umgegangen.'::text,'wärst'::text,'fuhrst'::text,'würdest'::text,'Du wünschst dir, du wärst nicht mit den Teetassen gefahren, aber mit der Übelkeit bist du echt tapfer umgegangen.'::text),
(386890,42988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти хотів би, щоб ... на тих чашках, але з нудотою ти впорався мужньо, чесно.'::text,'не катався'::text,'не катався'::text,'не катався б'::text,'Ти хотів би, щоб не катався на тих чашках, але з нудотою ти впорався мужньо, чесно.'::text),
(386889,42988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearías no ... a esas tazas, pero la verdad es que llevaste el mareo con mucha valentía.'::text,'haberte subido'::text,'subirte'::text,'subirte'::text,'Desearías no haberte subido a esas tazas, pero la verdad es que llevaste el mareo con mucha valentía.'::text),
(386888,42988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu aimerais ne pas ... ces tasses, mais franchement, tu as géré le malaise avec courage.'::text,'avoir fait'::text,'faire'::text,'faire'::text,'Tu aimerais ne pas avoir fait ces tasses, mais franchement, tu as géré le malaise avec courage.'::text),
(386891,42988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke o fincanlara ... diyorsun, ama mide bulantısıyla çok cesurca başa çıktın, açıkçası.'::text,'binmeseydim'::text,'binmesem'::text,'binmeyeceğim'::text,'Keşke o fincanlara binmeseydim diyorsun, ama mide bulantısıyla çok cesurca başa çıktın, açıkçası.'::text),
(386892,42988,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánod, bárcsak ... a csészékkel, de őszintén, bátran viselted a rosszullétet.'::text,'ne mentél volna'::text,'ne mennél'::text,'ne mennél'::text,'Azt kívánod, bárcsak ne mentél volna a csészékkel, de őszintén, bátran viselted a rosszullétet.'::text),
(386895,42989,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Teetassen-Karussell, ... die ganze Übelkeit verursacht hatte, drehte sich hinter ihnen weiter.'::text,'das'::text,'das'::text,'wer'::text,'Das Teetassen-Karussell, das die ganze Übelkeit verursacht hatte, drehte sich hinter ihnen weiter.'::text),
(386899,42989,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Атракціон із чашками, ... спричинив усю цю нудоту, далі крутився позаду них.'::text,'який'::text,'що'::text,'хто'::text,'Атракціон із чашками, який спричинив усю цю нудоту, далі крутився позаду них.'::text),
(386898,42989,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La atracción de las tazas, ... causó todo el mareo, seguía girando detrás de ellos.'::text,'que'::text,'que'::text,'quien'::text,'La atracción de las tazas, que causó todo el mareo, seguía girando detrás de ellos.'::text),
(386897,42989,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le manège des tasses, ... avait causé tout ce malaise, continuait de tourner derrière eux.'::text,'qui'::text,'qui'::text,'qui'::text,'Le manège des tasses, qui avait causé tout ce malaise, continuait de tourner derrière eux.'::text),
(386900,42989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bütün o mide bulantısına yol açan fincan oyuncağı arkalarında dönmeye devam etti.'::text,''::text,NULL::text,NULL::text,'Bütün o mide bulantısına yol açan fincan oyuncağı arkalarında dönmeye devam etti.'::text),
(386901,42989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csészés körhinta, ... az egész rosszullétet okozta, tovább forgott mögöttük.'::text,'amely'::text,'ami'::text,'aki'::text,'A csészés körhinta, amely az egész rosszullétet okozta, tovább forgott mögöttük.'::text),
(386904,42990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei vielen Fahrgästen beginnt ... oft nach ein paar Minuten in den Teetassen.'::text,'Übelkeit'::text,'eine Übelkeit'::text,'die Übelkeiten'::text,'Bei vielen Fahrgästen beginnt Übelkeit oft nach ein paar Minuten in den Teetassen.'::text),
(386908,42990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Для багатьох пасажирів ... часто починається після кількох хвилин на чашках.'::text,'нудота'::text,'нудота'::text,'нудоти'::text,'Для багатьох пасажирів нудота часто починається після кількох хвилин на чашках.'::text),
(386907,42990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para muchos pasajeros, ... suele empezar tras unos minutos en las tazas.'::text,'el mareo'::text,'un mareo'::text,'los mareos'::text,'Para muchos pasajeros, el mareo suele empezar tras unos minutos en las tazas.'::text),
(386906,42990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pour beaucoup de passagers, ... commence souvent après quelques minutes dans les tasses.'::text,'le malaise'::text,'un malaise'::text,'les malaises'::text,'Pour beaucoup de passagers, le malaise commence souvent après quelques minutes dans les tasses.'::text),
(386909,42990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birçok yolcu için ... genellikle fincanlarda birkaç dakika geçtikten sonra başlar.'::text,'mide bulantısı'::text,'bir mide bulantısı'::text,'mide bulantıları'::text,'Birçok yolcu için mide bulantısı genellikle fincanlarda birkaç dakika geçtikten sonra başlar.'::text),
(386910,42990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sok utasnál ... gyakran már néhány perc után jelentkezik a csészékben.'::text,'a rosszullét'::text,'egy rosszullét'::text,'a rosszullétek'::text,'Sok utasnál a rosszullét gyakran már néhány perc után jelentkezik a csészékben.'::text),
(386913,42991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fahrgeschäfte drehten sich weiter, ... der Übelkeit der Leute an den Mülleimern.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Die Fahrgeschäfte drehten sich weiter, trotz der Übelkeit der Leute an den Mülleimern.'::text),
(386917,42991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Атракціони далі крутилися, ... нудоту людей біля смітників.'::text,'попри'::text,'хоча'::text,'через'::text,'Атракціони далі крутилися, попри нудоту людей біля смітників.'::text),
(386916,42991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las atracciones siguieron girando ... el mareo de la gente junto a las papeleras.'::text,'a pesar de'::text,'aunque'::text,'debido a'::text,'Las atracciones siguieron girando a pesar de el mareo de la gente junto a las papeleras.'::text),
(386915,42991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les manèges ont continué de tourner ... le malaise des gens près des poubelles.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'Les manèges ont continué de tourner malgré le malaise des gens près des poubelles.'::text),
(386918,42991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çöp kutularının yanındaki insanların mide bulantısına ... oyuncaklar dönmeye devam etti.'::text,'rağmen'::text,'her ne kadar'::text,'yüzünden'::text,'Çöp kutularının yanındaki insanların mide bulantısına rağmen oyuncaklar dönmeye devam etti.'::text),
(386919,42991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A körhinták tovább forogtak a kukáknál álló emberek rosszulléte ...'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A körhinták tovább forogtak a kukáknál álló emberek rosszulléte ellenére.'::text),
(386922,42992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird diese Übelkeit den halben Rummel ...! Totale Katastrophe!'::text,'erwischt haben'::text,'erwischen'::text,'erwischen'::text,'Bis heute Abend wird diese Übelkeit den halben Rummel erwischt haben! Totale Katastrophe!'::text),
(386926,42992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора ця нудота ... пів лунапарку! Повна катастрофа!'::text,'накриє'::text,'накриє'::text,'накриває'::text,'До вечора ця нудота накриє пів лунапарку! Повна катастрофа!'::text),
(386925,42992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche, este mareo ... a media feria! ¡Desastre total!'::text,'habrá afectado'::text,'afectará'::text,'afecta'::text,'¡Para esta noche, este mareo habrá afectado a media feria! ¡Desastre total!'::text),
(386924,42992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, ce malaise ... la moitié de la fête foraine ! Catastrophe totale !'::text,'aura frappé'::text,'frappera'::text,'frappe'::text,'D''ici ce soir, ce malaise aura frappé la moitié de la fête foraine ! Catastrophe totale !'::text),
(386927,42992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar bu mide bulantısı lunaparkın yarısını ...! Tam bir felaket!'::text,'vurmuş olacak'::text,'vuracak'::text,'vuruyor'::text,'Bu akşama kadar bu mide bulantısı lunaparkın yarısını vurmuş olacak! Tam bir felaket!'::text),
(386928,42992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére ez a rosszullét ... a fél vidámparkot! Totális katasztrófa!'::text,'leteríti'::text,'le fogja teríteni'::text,'teríti'::text,'Estére ez a rosszullét leteríti a fél vidámparkot! Totális katasztrófa!'::text),
(333381,37043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Schlange sich weiterbewegt, ... der junge Mann in einer Minute seinen Stimmzettel ein.'::text,'wirft'::text,'würfe'::text,'warf'::text,'Wenn die Schlange sich weiterbewegt, wirft der junge Mann in einer Minute seinen Stimmzettel ein.'::text),
(333385,37043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо черга й далі рухатиметься, юнак ... свій бюлетень за хвилину.'::text,'вкине'::text,'вкинув би'::text,'вкинув'::text,'Якщо черга й далі рухатиметься, юнак вкине свій бюлетень за хвилину.'::text),
(333384,37043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la cola sigue avanzando, el chico ... su papeleta en un minuto.'::text,'meterá'::text,'metería'::text,'metió'::text,'Si la cola sigue avanzando, el chico meterá su papeleta en un minuto.'::text),
(333383,37043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la file continue d''avancer, le jeune homme ... son bulletin dans une minute.'::text,'glissera'::text,'glisserait'::text,'a glissé'::text,'Si la file continue d''avancer, le jeune homme glissera son bulletin dans une minute.'::text),
(333386,37043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıra ilerlemeye devam ederse, genç adam bir dakika içinde oy pusulasını ...'::text,'atacak'::text,'atardı'::text,'attı'::text,'Sıra ilerlemeye devam ederse, genç adam bir dakika içinde oy pusulasını atacak.'::text),
(333387,37043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sor tovább halad, a fiatalember egy perc múlva ... a szavazólapját.'::text,'bedobja'::text,'bedobná'::text,'bedobta'::text,'Ha a sor tovább halad, a fiatalember egy perc múlva bedobja a szavazólapját.'::text),
(333390,37044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Urne keinen Schlitz hätte, ... die Wähler ihre Stimmzettel auf dem Tisch.'::text,'ließen'::text,'lassen'::text,'lassen'::text,'Wenn die Urne keinen Schlitz hätte, ließen die Wähler ihre Stimmzettel auf dem Tisch.'::text),
(333394,37044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в урні не було щілини, виборці ... свої бюлетені на столі.'::text,'залишали б'::text,'залишать'::text,'залишають'::text,'Якби в урні не було щілини, виборці залишали б свої бюлетені на столі.'::text),
(333393,37044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la urna no tuviera ranura, los votantes ... sus papeletas en la mesa.'::text,'dejarían'::text,'dejarán'::text,'dejan'::text,'Si la urna no tuviera ranura, los votantes dejarían sus papeletas en la mesa.'::text),
(333392,37044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''urne n''avait pas de fente, les électeurs ... leurs bulletins sur la table.'::text,'laisseraient'::text,'laisseront'::text,'laissent'::text,'Si l''urne n''avait pas de fente, les électeurs laisseraient leurs bulletins sur la table.'::text),
(333395,37044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandığın yarığı olmasaydı, seçmenler oy pusulalarını masada ...'::text,'bırakırdı'::text,'bırakacak'::text,'bırakıyor'::text,'Sandığın yarığı olmasaydı, seçmenler oy pusulalarını masada bırakırdı.'::text),
(333396,37044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az urnán nem lenne nyílás, a szavazók az asztalon ... a szavazólapjaikat.'::text,'hagynák'::text,'fogják hagyni'::text,'hagyják'::text,'Ha az urnán nem lenne nyílás, a szavazók az asztalon hagynák a szavazólapjaikat.'::text),
(333399,37045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, Gerüchten zufolge ... letztes Mal jeder Stimmzettel von Hand gezählt.'::text,'wurde'::text,'zählte'::text,'wird'::text,'Also, Gerüchten zufolge wurde letztes Mal jeder Stimmzettel von Hand gezählt.'::text),
(333403,37045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, минулого разу кожен бюлетень ... вручну.'::text,'був порахований'::text,'порахував'::text,'рахується'::text,'Отже, кажуть, минулого разу кожен бюлетень був порахований вручну.'::text),
(333402,37045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues dicen que la última vez cada papeleta ... a mano.'::text,'se contó'::text,'contó'::text,'se cuenta'::text,'Vale, pues dicen que la última vez cada papeleta se contó a mano.'::text),
(333401,37045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, alors, il paraît que la dernière fois, chaque bulletin ... à la main.'::text,'a été compté'::text,'a compté'::text,'est compté'::text,'Bon, alors, il paraît que la dernière fois, chaque bulletin a été compté à la main.'::text),
(333404,37045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, söylentiye göre geçen sefer her oy pusulası elle ...'::text,'sayıldı'::text,'saydı'::text,'sayılıyor'::text,'Tamam, söylentiye göre geçen sefer her oy pusulası elle sayıldı.'::text),
(333405,37045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, a pletyka szerint legutóbb minden szavazólapot kézzel ...'::text,'számoltak meg'::text,'megszámolt'::text,'számolnak meg'::text,'Szóval, a pletyka szerint legutóbb minden szavazólapot kézzel számoltak meg.'::text),
(333408,37046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau in Gelb ... ihren Stimmzettel durch den Schlitz und lächelte.'::text,'steckte'::text,'wurde gesteckt'::text,'steckend'::text,'Die Frau in Gelb steckte ihren Stimmzettel durch den Schlitz und lächelte.'::text),
(333412,37046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в жовтому ... свій бюлетень у щілину й усміхнулася.'::text,'вкинула'::text,'була вкинута'::text,'вкидаючи'::text,'Жінка в жовтому вкинула свій бюлетень у щілину й усміхнулася.'::text),
(333411,37046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer de amarillo ... su papeleta por la ranura y sonrió.'::text,'metió'::text,'fue metida'::text,'metiendo'::text,'La mujer de amarillo metió su papeleta por la ranura y sonrió.'::text),
(333410,37046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme en jaune ... son bulletin dans la fente et a souri.'::text,'a glissé'::text,'a été glissée'::text,'glissant'::text,'La femme en jaune a glissé son bulletin dans la fente et a souri.'::text),
(333413,37046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarılı kadın oy pusulasını yarıktan ... ve gülümsedi.'::text,'attı'::text,'atıldı'::text,'atarak'::text,'Sarılı kadın oy pusulasını yarıktan attı ve gülümsedi.'::text),
(333414,37046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sárga ruhás nő ... a szavazólapját a résen, és elmosolyodott.'::text,'bedobta'::text,'be lett dobva'::text,'bedobva'::text,'A sárga ruhás nő bedobta a szavazólapját a résen, és elmosolyodott.'::text),
(333417,37047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du lächelst, während du deinen Stimmzettel einwirfst, also ... du stolz auf deine Wahl sein. Respekt.'::text,'musst'::text,'kannst nicht'::text,'solltest'::text,'Du lächelst, während du deinen Stimmzettel einwirfst, also musst du stolz auf deine Wahl sein. Respekt.'::text),
(333421,37047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти усміхаєшся, коли вкидаєш бюлетень, тож ти ... пишатися своїм вибором. Респект.'::text,'мусиш'::text,'не можеш'::text,'маєш'::text,'Ти усміхаєшся, коли вкидаєш бюлетень, тож ти мусиш пишатися своїм вибором. Респект.'::text),
(333420,37047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonríes al meter tu papeleta, así que ... estar orgulloso de tu elección. Respeto.'::text,'debes de'::text,'no puedes'::text,'deberías'::text,'Sonríes al meter tu papeleta, así que debes de estar orgulloso de tu elección. Respeto.'::text),
(333419,37047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu souris en glissant ton bulletin, donc tu ... être fier de ton choix. Respect.'::text,'dois'::text,'ne peux pas'::text,'devrais'::text,'Tu souris en glissant ton bulletin, donc tu dois être fier de ton choix. Respect.'::text),
(333422,37047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oy pusulanı atarken gülümsüyorsun, demek ki seçiminle gurur ..., saygılar.'::text,'duyuyor olmalısın'::text,'duyuyor olamazsın'::text,'duymalısın'::text,'Oy pusulanı atarken gülümsüyorsun, demek ki seçiminle gurur duyuyor olmalısın, saygılar.'::text),
(333423,37047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mosolyogsz, ahogy bedobod a szavazólapodat, szóval ... a választásodra. Respekt.'::text,'biztosan büszke vagy'::text,'nem lehetsz büszke'::text,'büszkének kellene lenned'::text,'Mosolyogsz, ahogy bedobod a szavazólapodat, szóval biztosan büszke vagy a választásodra. Respekt.'::text),
(333435,37049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte sagte, dass die Stimmzettel am Ende des Tages ...'::text,'gezählt würden'::text,'gezählt werden'::text,'gezählt werden'::text,'Der Beamte sagte, dass die Stimmzettel am Ende des Tages gezählt würden.'::text),
(333439,37049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Службовець сказав, що бюлетені ... наприкінці дня.'::text,'порахують'::text,'порахують'::text,'рахують'::text,'Службовець сказав, що бюлетені порахують наприкінці дня.'::text),
(333438,37049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El funcionario dijo que las papeletas ... al final del día.'::text,'se contarían'::text,'se contarán'::text,'se cuentan'::text,'El funcionario dijo que las papeletas se contarían al final del día.'::text),
(333437,37049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le responsable a dit que les bulletins ... à la fin de la journée.'::text,'seraient comptés'::text,'seront comptés'::text,'sont comptés'::text,'Le responsable a dit que les bulletins seraient comptés à la fin de la journée.'::text),
(333440,37049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli oy pusulalarının gün sonunda ... söyledi.'::text,'sayılacağını'::text,'sayılacağını'::text,'sayıldığını'::text,'Görevli oy pusulalarının gün sonunda sayılacağını söyledi.'::text),
(333441,37049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztviselő azt mondta, hogy a szavazólapokat a nap végén ...'::text,'megszámolják'::text,'meg fogják számolni'::text,'számolják'::text,'A tisztviselő azt mondta, hogy a szavazólapokat a nap végén megszámolják.'::text),
(333444,37050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor Jahren ... die Leute ihre Stimmzettel hier in eine Holzurne.'::text,'steckten'::text,'waren es gewohnt'::text,'steckten'::text,'Vor Jahren steckten die Leute ihre Stimmzettel hier in eine Holzurne.'::text),
(333448,37050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колись люди ... свої бюлетені тут у дерев''яну урну.'::text,'вкидали'::text,'звикли вкидати'::text,'вкидали'::text,'Колись люди вкидали свої бюлетені тут у дерев''яну урну.'::text),
(333447,37050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace años, la gente ... sus papeletas en una urna de madera aquí.'::text,'metía'::text,'estaba acostumbrada a meter'::text,'metía'::text,'Hace años, la gente metía sus papeletas en una urna de madera aquí.'::text),
(333446,37050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a des années, les gens ... leurs bulletins dans une urne en bois ici.'::text,'glissaient'::text,'avaient l''habitude de glisser'::text,'glissaient'::text,'Il y a des années, les gens glissaient leurs bulletins dans une urne en bois ici.'::text),
(333449,37050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllar önce insanlar oy pusulalarını burada tahta bir sandığa ...'::text,'atarlardı'::text,'atmaya alışkındı'::text,'atarlardı'::text,'Yıllar önce insanlar oy pusulalarını burada tahta bir sandığa atarlardı.'::text),
(333450,37050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évekkel ezelőtt az emberek itt egy fadobozba ... a szavazólapjaikat.'::text,'dobták be'::text,'hozzá voltak szokva, hogy bedobják'::text,'dobták be'::text,'Évekkel ezelőtt az emberek itt egy fadobozba dobták be a szavazólapjaikat.'::text),
(333453,37051,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hielt inne, um seinen Stimmzettel zu ..., und schob ihn dann durch den Schlitz.'::text,'falten'::text,'falten'::text,'falten'::text,'Er hielt inne, um seinen Stimmzettel zu falten, und schob ihn dann durch den Schlitz.'::text),
(333457,37051,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зупинився, щоб ... свій бюлетень, а потім просунув його в щілину.'::text,'скласти'::text,'складати'::text,'скласти'::text,'Він зупинився, щоб скласти свій бюлетень, а потім просунув його в щілину.'::text),
(333456,37051,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se detuvo para ... su papeleta y luego la metió por la ranura.'::text,'doblar'::text,'doblar'::text,'doblar'::text,'Se detuvo para doblar su papeleta y luego la metió por la ranura.'::text),
(333455,37051,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il s''est arrêté pour ... son bulletin, puis l''a glissé dans la fente.'::text,'plier'::text,'plier'::text,'plier'::text,'Il s''est arrêté pour plier son bulletin, puis l''a glissé dans la fente.'::text),
(333458,37051,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oy pusulasını ... için durdu, sonra yarıktan itti.'::text,'katlamak'::text,'katlamak'::text,'katla'::text,'Oy pusulasını katlamak için durdu, sonra yarıktan itti.'::text),
(333459,37051,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megállt, hogy ... a szavazólapját, aztán betolta a résen.'::text,'összehajtsa'::text,'összehajtsa'::text,'összehajtsa'::text,'Megállt, hogy összehajtsa a szavazólapját, aztán betolta a résen.'::text),
(333462,37052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihren Stimmzettel schon seit zwanzig Minuten, und die Spannung ist absolut unerträglich!'::text,'hält'::text,'hält'::text,'hält'::text,'Sie hält ihren Stimmzettel schon seit zwanzig Minuten, und die Spannung ist absolut unerträglich!'::text),
(333466,37052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свій бюлетень уже двадцять хвилин, і напруга абсолютно нестерпна!'::text,'тримає'::text,'тримає'::text,'тримає'::text,'Вона тримає свій бюлетень уже двадцять хвилин, і напруга абсолютно нестерпна!'::text),
(333465,37052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lleva veinte minutos ... su papeleta y la tensión es absolutamente insoportable!'::text,'sujetando'::text,'sujetando'::text,'sujetando'::text,'¡Lleva veinte minutos sujetando su papeleta y la tensión es absolutamente insoportable!'::text),
(333464,37052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son bulletin depuis vingt minutes, et la tension est absolument insupportable !'::text,'tient'::text,'tient'::text,'tient'::text,'Elle tient son bulletin depuis vingt minutes, et la tension est absolument insupportable !'::text),
(333467,37052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yirmi dakikadır oy pusulasını elinde ... ve gerilim kesinlikle dayanılmaz!'::text,'tutuyor'::text,'tutuyor'::text,'tutar'::text,'Yirmi dakikadır oy pusulasını elinde tutuyor ve gerilim kesinlikle dayanılmaz!'::text),
(333468,37052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már húsz perce ... a szavazólapját, és a feszültség abszolút elviselhetetlen!'::text,'szorongatja'::text,'szorongatja'::text,'szorongatja'::text,'Már húsz perce szorongatja a szavazólapját, és a feszültség abszolút elviselhetetlen!'::text),
(346305,38479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du versprichst, bei jeder einzelnen Wahl ..., und ehrlich, genau das braucht die Demokratie.'::text,'wählen zu gehen'::text,'wählen zu gehen'::text,'wählen zu gehen'::text,'Du versprichst, bei jeder einzelnen Wahl wählen zu gehen, und ehrlich, genau das braucht die Demokratie.'::text),
(346309,38479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти обіцяєш, що ... на кожних виборах, і, чесно, саме цього потребує демократія.'::text,'голосуватимеш'::text,'голосуватимеш'::text,'голосуєш'::text,'Ти обіцяєш, що голосуватимеш на кожних виборах, і, чесно, саме цього потребує демократія.'::text),
(346308,38479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometes que ... en todas y cada una de las elecciones, y la verdad, eso es lo que necesita la democracia.'::text,'votarás'::text,'estarás votando'::text,'votas'::text,'Prometes que votarás en todas y cada una de las elecciones, y la verdad, eso es lo que necesita la democracia.'::text),
(346307,38479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu promets que tu ... à chaque élection, et franchement, c''est ce dont la démocratie a besoin.'::text,'voteras'::text,'seras en train de voter'::text,'votes'::text,'Tu promets que tu voteras à chaque élection, et franchement, c''est ce dont la démocratie a besoin.'::text),
(346310,38479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her bir seçimde ... söz veriyorsun ve açıkçası, demokrasinin ihtiyacı da tam bu.'::text,'oy vereceğine'::text,'oy veriyor olacağına'::text,'oy verdiğine'::text,'Her bir seçimde oy vereceğine söz veriyorsun ve açıkçası, demokrasinin ihtiyacı da tam bu.'::text),
(346311,38479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéred, hogy minden egyes választáson ..., és őszintén, pont erre van szüksége a demokráciának.'::text,'szavazni fogsz'::text,'szavazni fogsz'::text,'szavazol'::text,'Megígéred, hogy minden egyes választáson szavazni fogsz, és őszintén, pont erre van szüksége a demokráciának.'::text),
(346314,38480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du mit so einer Energie wählst, ... sich Demokratie ehrlich gesagt viel lustiger an.'::text,'fühlt'::text,'fühlte'::text,'fühlt'::text,'Wenn du mit so einer Energie wählst, fühlt sich Demokratie ehrlich gesagt viel lustiger an.'::text),
(346318,38480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти голосуєш з такою енергією, демократія ... значно веселішою, чесно.'::text,'здається'::text,'здавалася'::text,'здаватиметься'::text,'Коли ти голосуєш з такою енергією, демократія здається значно веселішою, чесно.'::text),
(346317,38480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si votas con esa energía, la democracia ... mucho más divertida, la verdad.'::text,'parece'::text,'parecía'::text,'parecerá'::text,'Si votas con esa energía, la democracia parece mucho más divertida, la verdad.'::text),
(346316,38480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand tu votes avec autant d''énergie, la démocratie ... bien plus fun, franchement.'::text,'paraît'::text,'paraissait'::text,'paraîtra'::text,'Quand tu votes avec autant d''énergie, la démocratie paraît bien plus fun, franchement.'::text),
(346319,38480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle bir enerjiyle oy verince demokrasi çok daha eğlenceli ..., açıkçası.'::text,'geliyor'::text,'geliyordu'::text,'gelecek'::text,'Böyle bir enerjiyle oy verince demokrasi çok daha eğlenceli geliyor, açıkçası.'::text),
(346320,38480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ilyen energiával szavazol, a demokrácia sokkal szórakoztatóbbnak ..., őszintén.'::text,'tűnik'::text,'tűnt'::text,'fog tűnni'::text,'Ha ilyen energiával szavazol, a demokrácia sokkal szórakoztatóbbnak tűnik, őszintén.'::text),
(346323,38481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Demokratie sieht in diesem Saal sehr aufregend aus, ...? Eindeutig die Party des Jahres.'::text,'oder'::text,'oder'::text,'oder'::text,'Die Demokratie sieht in diesem Saal sehr aufregend aus, oder? Eindeutig die Party des Jahres.'::text),
(346327,38481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Демократія виглядає дуже захопливо в цій залі, ...? Явно вечірка року.'::text,'правда'::text,'правда'::text,'правда'::text,'Демократія виглядає дуже захопливо в цій залі, правда? Явно вечірка року.'::text),
(346326,38481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La democracia parece muy emocionante en esta sala, ¿...? Claramente la fiesta del año.'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La democracia parece muy emocionante en esta sala, ¿verdad? Claramente la fiesta del año.'::text),
(346325,38481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La démocratie a l''air très excitante dans cette salle, ... ? Clairement la fête de l''année.'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'La démocratie a l''air très excitante dans cette salle, pas vrai ? Clairement la fête de l''année.'::text),
(346328,38481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demokrasi bu salonda çok heyecan verici görünüyor, ...? Belli ki yılın partisi.'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Demokrasi bu salonda çok heyecan verici görünüyor, değil mi? Belli ki yılın partisi.'::text),
(346329,38481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A demokrácia nagyon izgalmasnak tűnik ebben a teremben, ...? Nyilván az év bulija.'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A demokrácia nagyon izgalmasnak tűnik ebben a teremben, ugye? Nyilván az év bulija.'::text),
(346332,38482,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann liebt die Demokratie, und ... der ältere Mann. Offensichtlich eine wilde Truppe.'::text,'genauso'::text,'genauso'::text,'ebenso wenig'::text,'Der junge Mann liebt die Demokratie, und genauso der ältere Mann. Offensichtlich eine wilde Truppe.'::text),
(346336,38482,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Юнак любить демократію, і ... старший чоловік. Явно шалена компанія.'::text,'так само'::text,'так само'::text,'так само не'::text,'Юнак любить демократію, і так само старший чоловік. Явно шалена компанія.'::text),
(346335,38482,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al joven le encanta la democracia, y ... al hombre mayor. Claramente, un público salvaje.'::text,'también'::text,'también'::text,'tampoco'::text,'Al joven le encanta la democracia, y también al hombre mayor. Claramente, un público salvaje.'::text),
(346334,38482,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme adore la démocratie, ... l''homme plus âgé. Clairement une foule déchaînée.'::text,'tout comme'::text,'tout comme'::text,'pas plus que'::text,'Le jeune homme adore la démocratie, tout comme l''homme plus âgé. Clairement une foule déchaînée.'::text),
(346337,38482,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam demokrasiyi seviyor, yaşlı adam ..., belli ki çılgın bir ekip.'::text,'da öyle'::text,'da öyle'::text,'da sevmiyor'::text,'Genç adam demokrasiyi seviyor, yaşlı adam da öyle, belli ki çılgın bir ekip.'::text),
(346338,38482,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember imádja a demokráciát, és ... az idősebb férfi. Nyilván vad társaság.'::text,'ugyanígy'::text,'ugyanígy'::text,'ugyanígy nem'::text,'A fiatalember imádja a demokráciát, és ugyanígy az idősebb férfi. Nyilván vad társaság.'::text),
(346341,38483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird die Demokratie ihre Arbeit ..., und jeder Zettel wird in der Urne sein.'::text,'getan haben'::text,'tun'::text,'tun'::text,'Bis heute Abend wird die Demokratie ihre Arbeit getan haben, und jeder Zettel wird in der Urne sein.'::text),
(346345,38483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора демократія ... свою роботу, і кожен папірець буде в урні.'::text,'зробить'::text,'зробить'::text,'робить'::text,'До вечора демократія зробить свою роботу, і кожен папірець буде в урні.'::text),
(346344,38483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, la democracia ... su trabajo y cada papel estará en la urna.'::text,'habrá hecho'::text,'hará'::text,'hace'::text,'Para esta noche, la democracia habrá hecho su trabajo y cada papel estará en la urna.'::text),
(346343,38483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, la démocratie ... son travail, et chaque bulletin sera dans l''urne.'::text,'aura fait'::text,'fera'::text,'fait'::text,'D''ici ce soir, la démocratie aura fait son travail, et chaque bulletin sera dans l''urne.'::text),
(346346,38483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar demokrasi işini ... ve her kâğıt sandıkta olacak.'::text,'yapmış olacak'::text,'yapacak'::text,'yapıyor'::text,'Bu akşama kadar demokrasi işini yapmış olacak ve her kâğıt sandıkta olacak.'::text),
(346347,38483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére a demokrácia ... a dolgát, és minden papír az urnában lesz.'::text,'elvégzi'::text,'elvégzi'::text,'végzi'::text,'Estére a demokrácia elvégzi a dolgát, és minden papír az urnában lesz.'::text),
(346359,38485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau in Senfgelb gab zu, den ganzen Vormittag über Demokratie ...'::text,'geredet zu haben'::text,'zu reden'::text,'redete'::text,'Die Frau in Senfgelb gab zu, den ganzen Vormittag über Demokratie geredet zu haben.'::text),
(346363,38485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в гірчичному зізналася, що ... про демократію весь ранок.'::text,'говорила'::text,'говорити'::text,'говорила'::text,'Жінка в гірчичному зізналася, що говорила про демократію весь ранок.'::text),
(346362,38485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer de mostaza admitió ... de democracia toda la mañana.'::text,'haber estado hablando'::text,'hablar'::text,'habló'::text,'La mujer de mostaza admitió haber estado hablando de democracia toda la mañana.'::text),
(346361,38485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme en moutarde a avoué ... de démocratie toute la matinée.'::text,'avoir parlé'::text,'parler'::text,'a parlé'::text,'La femme en moutarde a avoué avoir parlé de démocratie toute la matinée.'::text),
(346364,38485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hardal renkli giyinen kadın bütün sabah demokrasi hakkında ... itiraf etti.'::text,'konuştuğunu'::text,'konuşmayı'::text,'konuştu'::text,'Hardal renkli giyinen kadın bütün sabah demokrasi hakkında konuştuğunu itiraf etti.'::text),
(346365,38485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mustársárga ruhás nő bevallotta, hogy egész délelőtt a demokráciáról ...'::text,'beszélt'::text,'beszélni'::text,'beszélt'::text,'A mustársárga ruhás nő bevallotta, hogy egész délelőtt a demokráciáról beszélt.'::text),
(346368,38486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Demokratie hätte ohne diese Wähler nicht überleben ..., es wäre das Ende!'::text,'können'::text,'dürfen'::text,'sollen'::text,'Die Demokratie hätte ohne diese Wähler nicht überleben können, es wäre das Ende!'::text),
(346372,38486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Демократія ... вижити без цих виборців. Це був би кінець!'::text,'не змогла б'::text,'не мусила б'::text,'не мала б'::text,'Демократія не змогла б вижити без цих виборців. Це був би кінець!'::text),
(346371,38486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La democracia ... sin estos votantes. ¡Sería el final!'::text,'no habría podido sobrevivir'::text,'no debe de haber sobrevivido'::text,'no debería haber sobrevivido'::text,'La democracia no habría podido sobrevivir sin estos votantes. ¡Sería el final!'::text),
(346370,38486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La démocratie ... survivre sans ces électeurs. Ce serait la fin !'::text,'n''aurait pas pu'::text,'n''aurait pas dû'::text,'n''aurait pas dû'::text,'La démocratie n''aurait pas pu survivre sans ces électeurs. Ce serait la fin !'::text),
(346373,38486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu seçmenler olmadan demokrasi ..., bu son olurdu!'::text,'hayatta kalamazdı'::text,'hayatta kalmamış olmalı'::text,'hayatta kalmamalıydı'::text,'Bu seçmenler olmadan demokrasi hayatta kalamazdı, bu son olurdu!'::text),
(346374,38486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A demokrácia ezek nélkül a szavazók nélkül ... túlélni. Az lenne a vég!'::text,'nem tudta volna'::text,'nem kellett volna'::text,'nem kellett volna'::text,'A demokrácia ezek nélkül a szavazók nélkül nem tudta volna túlélni. Az lenne a vég!'::text),
(346377,38487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor: Laut dem Beamten hat der Helfer alle dazu gebracht, ihre Zettel zu ...'::text,'falten'::text,'falten'::text,'gefaltet'::text,'Stell dir vor: Laut dem Beamten hat der Helfer alle dazu gebracht, ihre Zettel zu falten.'::text),
(346381,38487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: за словами службовця, помічник змусив усіх ... свої папірці.'::text,'скласти'::text,'скласти'::text,'складені'::text,'Уяви: за словами службовця, помічник змусив усіх скласти свої папірці.'::text),
(346380,38487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fíjate: según el funcionario, el ayudante hizo que todos ... sus papeletas.'::text,'doblaran'::text,'doblaran'::text,'doblados'::text,'Fíjate: según el funcionario, el ayudante hizo que todos doblaran sus papeletas.'::text),
(346379,38487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : d''après le responsable, l''assistant a fait ... leurs bulletins à tout le monde.'::text,'plier'::text,'plier'::text,'plié'::text,'Écoute ça : d''après le responsable, l''assistant a fait plier leurs bulletins à tout le monde.'::text),
(346382,38487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: görevliye göre yardımcı herkese kâğıtlarını ...'::text,'katlattı'::text,'katlattı'::text,'katlanmış'::text,'Şuna bak: görevliye göre yardımcı herkese kâğıtlarını katlattı.'::text),
(346383,38487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld: a tisztviselő szerint a segítő mindenkivel ... a papírját.'::text,'összehajtatta'::text,'összehajtatta'::text,'összehajtva'::text,'Képzeld: a tisztviselő szerint a segítő mindenkivel összehajtatta a papírját.'::text),
(346386,38488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir gesagt, sie wünscht sich, die Demokratie ... jeden Tag so lustig.'::text,'wäre'::text,'ist'::text,'wird'::text,'Bestie, sie hat mir gesagt, sie wünscht sich, die Demokratie wäre jeden Tag so lustig.'::text),
(346390,38488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що хотіла б, щоб демократія ... такою веселою щодня.'::text,'була'::text,'є'::text,'буде'::text,'Подруго, вона сказала мені, що хотіла б, щоб демократія була такою веселою щодня.'::text),
(346389,38488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ojalá la democracia ... así de divertida todos los días.'::text,'fuera'::text,'es'::text,'será'::text,'Amiga, me dijo que ojalá la democracia fuera así de divertida todos los días.'::text),
(346388,38488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''elle aimerait que la démocratie ... aussi fun tous les jours.'::text,'soit'::text,'est'::text,'sera'::text,'Ma belle, elle m''a dit qu''elle aimerait que la démocratie soit aussi fun tous les jours.'::text),
(346391,38488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana demokrasinin her gün bu kadar eğlenceli ... istediğini söyledi.'::text,'olmasını'::text,'olduğunu'::text,'olacağını'::text,'Kanka, bana demokrasinin her gün bu kadar eğlenceli olmasını istediğini söyledi.'::text),
(346392,38488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, azt szeretné, ha a demokrácia minden nap ilyen szórakoztató ...'::text,'lenne'::text,NULL::text,'lesz'::text,'Csajszi, azt mondta, azt szeretné, ha a demokrácia minden nap ilyen szórakoztató lenne.'::text),
(362982,40332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... er in dieses Tagebuch, seit das Schiff den Hafen verlassen hat.'::text,'schreibt'::text,'schreibt'::text,'schreibt'::text,'Mädel, anscheinend schreibt er in dieses Tagebuch, seit das Schiff den Hafen verlassen hat.'::text),
(362986,40332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... у той щоденник, відколи корабель вийшов із гавані.'::text,'пише'::text,'пише'::text,'пише'::text,'Подруго, кажуть, він пише у той щоденник, відколи корабель вийшов із гавані.'::text),
(362985,40332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... en ese diario desde que el barco salió del puerto.'::text,'lleva escribiendo'::text,'está escribiendo'::text,'escribe'::text,'Tía, al parecer lleva escribiendo en ese diario desde que el barco salió del puerto.'::text),
(362984,40332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... dans ce journal depuis que le bateau a quitté le port.'::text,'écrit'::text,'écrit'::text,'écrit'::text,'Meuf, apparemment il écrit dans ce journal depuis que le bateau a quitté le port.'::text),
(362987,40332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan gemi limandan ayrıldığından beri o günlüğe ...'::text,'yazıyor'::text,'yazıyor'::text,'yazar'::text,'Kızım, anlaşılan gemi limandan ayrıldığından beri o günlüğe yazıyor.'::text),
(362988,40332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azóta ... abba a naplóba, hogy a hajó elhagyta a kikötőt.'::text,'ír'::text,'ír'::text,'ír'::text,'Csajszi, állítólag azóta ír abba a naplóba, hogy a hajó elhagyta a kikötőt.'::text),
(362991,40333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, er ... von seinem Tagebuch auf, als er den Leuchtturm sah.'::text,'blickte'::text,'blickte gerade'::text,'blickt'::text,'Hör mal, ich hab gehört, er blickte von seinem Tagebuch auf, als er den Leuchtturm sah.'::text),
(362995,40333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що він ... від щоденника тієї ж секунди, як побачив маяк.'::text,'відірвав погляд'::text,'відривав погляд'::text,'відірвав погляд'::text,'Слухай, я чула, що він відірвав погляд від щоденника тієї ж секунди, як побачив маяк.'::text),
(362994,40333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que ... la vista del diario en cuanto vio el faro.'::text,'levantó'::text,'estaba levantando'::text,'ha levantado'::text,'Oye, me han dicho que levantó la vista del diario en cuanto vio el faro.'::text),
(362993,40333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''il ... les yeux de son journal à la seconde où il a vu le phare.'::text,'a levé'::text,'levait'::text,'a levé'::text,'Écoute, il paraît qu''il a levé les yeux de son journal à la seconde où il a vu le phare.'::text),
(362996,40333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, deniz fenerini gördüğü an günlüğünden başını ... duydum.'::text,'kaldırdığını'::text,'kaldırıyor olduğunu'::text,'kaldırmış olduğunu'::text,'Dinle, deniz fenerini gördüğü an günlüğünden başını kaldırdığını duydum.'::text),
(362997,40333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, úgy hallottam, abban a pillanatban ... fel a naplójából, amikor meglátta a világítótornyot.'::text,'nézett'::text,'nézett'::text,'nézett'::text,'Figyelj, úgy hallottam, abban a pillanatban nézett fel a naplójából, amikor meglátta a világítótornyot.'::text),
(363000,40334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Typ wünscht sich, er ... ein größeres Tagebuch mitgenommen, weil die Klippen echt krass sind.'::text,'hätte'::text,'hätte'::text,'hat'::text,'Der Typ wünscht sich, er hätte ein größeres Tagebuch mitgenommen, weil die Klippen echt krass sind.'::text),
(363004,40334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак хотів би ... більший щоденник, бо ті скелі просто нереальні.'::text,'взяти з собою'::text,'взяти з собою'::text,'взяти з собою'::text,'Чувак хотів би взяти з собою більший щоденник, бо ті скелі просто нереальні.'::text),
(363003,40334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tío desearía ... un diario más grande, porque esos acantilados son una locura.'::text,'haber traído'::text,'traer'::text,'haber traído'::text,'El tío desearía haber traído un diario más grande, porque esos acantilados son una locura.'::text),
(363002,40334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mec aimerait ... un plus grand journal, parce que ces falaises sont grave irréelles.'::text,'avoir pris'::text,'prendre'::text,'avoir pris'::text,'Le mec aimerait avoir pris un plus grand journal, parce que ces falaises sont grave irréelles.'::text),
(363005,40334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam keşke daha büyük bir günlük ... diyor, çünkü o kayalıklar resmen gerçek dışı.'::text,'getirseydim'::text,'getirsem'::text,'getirdim'::text,'Adam keşke daha büyük bir günlük getirseydim diyor, çünkü o kayalıklar resmen gerçek dışı.'::text),
(363006,40334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csávó azt kívánja, bárcsak nagyobb naplót ..., mert azok a sziklák elég durvák.'::text,'hozott volna'::text,'hozna'::text,'hozott'::text,'A csávó azt kívánja, bárcsak nagyobb naplót hozott volna, mert azok a sziklák elég durvák.'::text),
(363009,40335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine schwarze Tagebuch, in ... er jeden Tag schreibt, hat einen festen Einband.'::text,'das'::text,'wer'::text,'das'::text,'Das kleine schwarze Tagebuch, in das er jeden Tag schreibt, hat einen festen Einband.'::text),
