(363012,40335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pequeño diario negro, en ... escribe cada día, tiene tapa dura.'::text,'el que'::text,'quien'::text,'el que'::text,'El pequeño diario negro, en el que escribe cada día, tiene tapa dura.'::text),
(363011,40335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit journal noir, dans ... il écrit tous les jours, a une couverture rigide.'::text,'lequel'::text,'qui'::text,'lequel'::text,'Le petit journal noir, dans lequel il écrit tous les jours, a une couverture rigide.'::text),
