(363015,40335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis fekete napló, ... minden nap ír, kemény fedelű.'::text,'amelybe'::text,'akibe'::text,'amibe'::text,'A kis fekete napló, amelybe minden nap ír, kemény fedelű.'::text),
(363018,40336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er führt Tagebuch, während er auf ... ist, weit weg vom Hafen.'::text,'See'::text,'der See'::text,'einer See'::text,'Er führt Tagebuch, während er auf See ist, weit weg vom Hafen.'::text),
(363022,40336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він веде щоденник, поки перебуває в ..., далеко від гавані.'::text,'морі'::text,'морі'::text,'морі'::text,'Він веде щоденник, поки перебуває в морі, далеко від гавані.'::text),
(363021,40336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lleva un diario mientras está en ..., lejos del puerto.'::text,'el mar'::text,'el mar'::text,'un mar'::text,'Lleva un diario mientras está en el mar, lejos del puerto.'::text),
(363020,40336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il tient un journal pendant qu''il est en ..., loin du port.'::text,'mer'::text,'la mer'::text,'une mer'::text,'Il tient un journal pendant qu''il est en mer, loin du port.'::text),
(363023,40336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Limandan uzakta, ... iken günlük tutuyor.'::text,'denizde'::text,'denizde'::text,'bir denizde'::text,'Limandan uzakta, denizde iken günlük tutuyor.'::text),
(363024,40336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplót vezet, amíg ... van, messze a kikötőtől.'::text,'tengeren'::text,'a tengeren'::text,'egy tengeren'::text,'Naplót vezet, amíg tengeren van, messze a kikötőtől.'::text),
(363027,40337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der rauen Wellen schrieb er, an den Mast gelehnt, weiter in sein Tagebuch.'::text,'Trotz'::text,'Wegen'::text,'Im Falle'::text,'Trotz der rauen Wellen schrieb er, an den Mast gelehnt, weiter in sein Tagebuch.'::text),
(363031,40337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... бурхливі хвилі, він далі писав у щоденник, притулившись до щогли.'::text,'Попри'::text,'Через'::text,'У разі'::text,'Попри бурхливі хвилі, він далі писав у щоденник, притулившись до щогли.'::text),
(363030,40337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... las olas bravas, siguió escribiendo en su diario apoyado en el mástil.'::text,'Pese a'::text,'Debido a'::text,'En caso de'::text,'Pese a las olas bravas, siguió escribiendo en su diario apoyado en el mástil.'::text),
(363029,40337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... les vagues déchaînées, il a continué d''écrire dans son journal contre le mât.'::text,'Malgré'::text,'En raison de'::text,'En cas de'::text,'Malgré les vagues déchaînées, il a continué d''écrire dans son journal contre le mât.'::text),
(363032,40337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sert dalgalara ..., direğe yaslanıp günlüğüne yazmaya devam etti.'::text,'rağmen'::text,'yüzünden'::text,'durumunda'::text,'Sert dalgalara rağmen, direğe yaslanıp günlüğüne yazmaya devam etti.'::text),
(363033,40337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A viharos hullámok ... tovább írt a naplójába az árbocnak dőlve.'::text,'ellenére'::text,'miatt'::text,'esetén'::text,'A viharos hullámok ellenére tovább írt a naplójába az árbocnak dőlve.'::text),
(363036,40338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich eine ruhige Reise: Er wusste, dass sein Tagebuch voll ..., wenn sie an den Klippen vorbeifuhren.'::text,'sein würde'::text,'sein wird'::text,'war'::text,'Offensichtlich eine ruhige Reise: Er wusste, dass sein Tagebuch voll sein würde, wenn sie an den Klippen vorbeifuhren.'::text),
(363040,40338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, спокійна подорож: він знав, що його щоденник ... заповнений, коли вони пропливуть повз скелі.'::text,'буде'::text,'буде'::text,'був'::text,'Очевидно, спокійна подорож: він знав, що його щоденник буде заповнений, коли вони пропливуть повз скелі.'::text),
(363039,40338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un viaje tranquilo, está claro: sabía que su diario ... lleno para cuando pasaran los acantilados.'::text,'estaría'::text,'estará'::text,'estaba'::text,'Un viaje tranquilo, está claro: sabía que su diario estaría lleno para cuando pasaran los acantilados.'::text),
(363038,40338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un voyage calme, évidemment : il savait que son journal ... plein au moment où ils passeraient les falaises.'::text,'serait'::text,'sera'::text,'était'::text,'Un voyage calme, évidemment : il savait que son journal serait plein au moment où ils passeraient les falaises.'::text),
(363041,40338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sakin bir yolculuk: sarp kayalıkları geçtiklerinde günlüğünün dolmuş ... biliyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Belli ki sakin bir yolculuk: sarp kayalıkları geçtiklerinde günlüğünün dolmuş olacağını biliyordu.'::text),
(363042,40338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nyugis út: tudta, hogy mire elhaladnak a sziklák mellett, a naplója tele ...'::text,'lesz'::text,'lesz'::text,'volt'::text,'Nyilván nyugis út: tudta, hogy mire elhaladnak a sziklák mellett, a naplója tele lesz.'::text),
(363054,40340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur eine kleine Aussicht: Er ... stundenlang in sein Tagebuch geschrieben, bevor er staunend aufblickte.'::text,'hatte'::text,'hat'::text,'hat'::text,'Nur eine kleine Aussicht: Er hatte stundenlang in sein Tagebuch geschrieben, bevor er staunend aufblickte.'::text),
(363058,40340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише невеличкий краєвид: він ... у щоденнику годинами, перш ніж здивовано підняв очі.'::text,'писав'::text,'писав'::text,'написав'::text,'Лише невеличкий краєвид: він писав у щоденнику годинами, перш ніж здивовано підняв очі.'::text),
